***************************************************************************************                   Line Edit v2.3**       Copyright Apple Computer, Inc. 1986-1992*                 All Rights Reserved**                Written by Cheryl Ewy**** March 88	Harry Yee** Converted to MAX** March 23 88	Steven Glass** Changed JMPs to end call routines to JMLs so same code can work in ROM.** May 5, 1988 v2.1d2   Dan O. & Harry Y** Call LETextBox2, TERec handle was not being locked when the ptr to it was being* used. Problem arose memory got compacted and this ptr moved. The handle is now* being locked.** June 15, 1988	   Harry Yee** Took prototype bit out of LEVerNum for final release on System Disk 3.2.** 15 Jun 88	Steven Glass** LECopy did not check for the case where there was no selection. This led to* memory trashing.** 11 Jul 88	Steven Glass** LETextBox2 now saves and restores all the text in the grafPort.*** 05 Aug 88	Steven Glass** LETextBox2 could leave a handle un-disposed if the bounding box was not valid.** In addition, LETextBox2 did not return a valid error code (when it worked or* when it did not).** 12 Oct 88	Steven Glass** Added entry: GetLEDefPRoc to call table.  Added defproc to link process.** 15 Feb 89	Harry Yee** Extracted all the equates and put in separate file.  This file, LineEditEquates.asm,* is now "included".** 4/9/89	glass & mensch** Added loop in tripleclick section of LEClick that removes the mouseUp event from the* event queue.** 15 May 89	Steven Glass** Made the defproc a dynamic segment that is loaded  automatically when the GetLEProc* address call is made. Added entry point FakeGetLEDefProc to do this.** Changed version number to 8301.** 12 Jun 89	Steven Glass** Minor Change to LENew.** 01 Sep 89	Harry Yee** Fix bug in LEFromScrap.  Two bytes of memory get trashed when the call LEFromScrap is* made and the  desk scrap is empty. The word that gets trashed is  $FFFE from where the* line edit scrap is located.** 19-Sep-90	Dave Lyons** Rolled version to $8303 (for change to LE Defproc for shift-clicking).** Removed dependency on all.macros.** Prettied up a few things (marked with 19-Sep-90 DAL).** 22-Sep-90	Dave Lyons** Added 2 lines in LETextBox setup so that the stack gets cleaned up properly if the Length* parameter is 0.** 11-Mar-91	Dave Lyons** Changed default password character to a hollow diamond ($D7) instead of an asterisk.** Implementing horizontal scrolling.  Added leHScrollPos field to end of LE Record (in* LineEditEquates.asm).** It doesn't work perfectly yet, but it kinda works enough for now.** 14-Mar-91	Dave Lyons** Mouse-dragging now tries to scroll only if the thing is left justified.** 8-May-91	Dave Lyons** Changed some PUSHLONG #0 into PHA PHA.** 14-May-91	Dave Lyons** Make scrolling not crash.  Added new entry point FindPoint2 to FindPoint, which returns* <selPoint as a character offset even if the point was not  inside the viewRect.** Dragging to above the view rect counts as the left;  dragging below counts as the* rightmost character.** Made Hilite respect leHScrollPos correctly.** 22-Aug-91	Dave Lyons** LETextBox2 was leaving the first line blank if there  was no place to break on the first* line.  Fixed.  Also made some optimizations (don't allocate a separate handle for getting* Font Globals!).** Comment out some dead equates, and the partial support for "equal tempered lines"(?),* whatever that is.** 4-Sep-91	Dave Lyons** Fixed a bug in LETextBox2:  If there was a formatting code and then there was nowhere to* break the first line, we would drop down a line before printing any text.  (This was* bugging Monte in Archiver.)  New variables: oldCurrentHeight, PrintedSomeChars.** 5-Sep-91	Dave Lyons** Default password character is symbolic (defaultPWChar).  No code change in this file.** 13-Jan-92	Dave Lyons** Make LESetText unscroll the edit line field (side-effect: SetLETextByID unscrolls).** 22-Jan-92	Dave Lyons** Fix bogus scrolling things.* ¥If you drag off the left and are already unscrolled, it doesn't flicker.* ¥If you drag off the left of the window, FindPoint now counts as to the left of the LE*  item, not the right.* ¥Scrolling is clamped to MaxScrollPos, which is computed from the width of the text*  compared to the width of the dest rectangle.* ¥Shift + arrow keys now properly hilites the selection.* ¥ReDraw erases the area to the left of the destRect but inside the viewRect only when*  the horizontal scroll position actually changes (for compatibility with Stephen Chick's*  Find File v1.20).* ¥If the LE record's destRect has width zero, then the field never scrolls (for text items*  AWGS 1.1 Graphics module).* ¥LESetSelect properly unscrolls the field, even if the insertion point is at the right*  edge of a scrolled item.** 5-Feb-92	Dave Lyons** Version $0303 for 6.0 final (changed in LineEditEquates.asm).**************************************************************************************** Begin 6.0.1** 20-Mar-92	Dave Lyons** Version $8304.** Added new IsSpecialLEKey call to see if an event is a* LE editing key.** 23-Mar-92	Dave Lyons** Replaced IsSpecialLEKey with LEClassifyKey, which returns* more information.** 22-Mar-93	Dave Lyons** Made LESetText erase the "gap" on the left of a scrolled field.** 1-Apr-93	Steve Stephenson** Changed version to $0304 for 6.0.1 (final)**************************************************************************************	print nogen	print push,off	include 'All.Macros'	include 'e16.quickdraw'	include 'e16.event'		;20-Mar-92 DAL	print pop		include 'LineEditEquates.asm'	MACRO	PushZPtr &A	pea  $0000	tdc	clc	adc  #&A	pha	MEND	MACRO	PushZLong &A	pei &A+2	pei &A	MEND	MACRO	PushZWord &A	pei  &A	MEND;-----------------------------------------------;;           Forward	address and entries;;-----------------------------------------------	ENTRY LEGetTextLen	ENTRY LEGetTextHand	ENTRY LESetJust	ENTRY LETextBox2	ENTRY LESetCaret	ENTRY LESetHilite	ENTRY LESetScrapLen	ENTRY LEGetScrapLen	ENTRY LEScrapHandle	ENTRY LEToScrap	ENTRY LEFromScrap	ENTRY LETextBox	ENTRY LEUpdate	ENTRY LEInsert	ENTRY LEDelete	ENTRY LEPaste	ENTRY LECopy	ENTRY LECut	ENTRY LEKey	ENTRY LEDeactivate	ENTRY LEActivate	ENTRY LESetSelect	ENTRY LEClick	ENTRY LEIdle	ENTRY LESetText	ENTRY LEDispose	ENTRY LENew	ENTRY oStdEnd0	ENTRY LEActive	ENTRY LEReset	ENTRY LEVersion	ENTRY LEShutDown	ENTRY LEStartUp	ENTRY LEBootInit	ENTRY STDERR4	ENTRY STDEND4	ENTRY STDEND0	ENTRY LOCKREC	ENTRY UNLOCKREC	ENTRY STDENTRY	ENTRY STDEXIT	ENTRY STDEND	ENTRY DRAWCARET	ENTRY FINDPOINT	ENTRY FindPoint2	;14-May-91 DAL	ENTRY HIDECARET	ENTRY HILITE	ENTRY FINDWORD	ENTRY SHOWCARET	ENTRY HILITE2	ENTRY CLEANUPSEL	ENTRY CMPSEL	ENTRY SELSORT	ENTRY SAVESTARTPROC	ENTRY DELETEGUTS	ENTRY REDRAW	ENTRY PASTEGUTS	ENTRY CALCSELLEN	ENTRY CALCSTARTPTR	ENTRY LOCKSCRAP	ENTRY UNLOCKSCRAP	ENTRY INSERTGUTS	ENTRY STDENTRY2	ENTRY STDERR0	ENTRY LOCKLINE2	ENTRY UNLOCKLINE	ENTRY GETSELRECT	ENTRY INVERTHOOK	ENTRY LOCKLINE	ENTRY CEXIT	ENTRY BEXIT	ENTRY AEXIT	ENTRY STDERR	ENTRY HOOKCOMMON	ENTRY MeasureThisText	ENTRY DrawThisText	entry LEClassifyKey		;20-Mar-92 DAL		;-----------------------------------------------;; Global Imports;;-----------------------------------------------	IMPORT OENDCALL	IMPORT ERROUT	IMPORT ENDCALL	IMPORT OERROUT****************************************************************** LINE EDIT CALL TABLE*****************************************************************	Export LECallTableLECallTable	PROC	import FakeGetLEDefProcTheStart	DC.L (TheEnd-TheStart)/4 	;num calls + 1	DC.L LEBootInit-1	DC.L LEStartUp-1	DC.L LEShutDown-1	DC.L LEVersion-1	DC.L LEReset-1	DC.L LEActive-1	DC.L oStdEnd0-1	DC.L oStdEnd0-1	DC.L LENew-1	DC.L LEDispose-1	DC.L LESetText-1	DC.L LEIdle-1	DC.L LEClick-1	DC.L LESetSelect-1	DC.L LEActivate-1	DC.L LEDeactivate-1	DC.L LEKey-1	DC.L LECut-1	DC.L LECopy-1	DC.L LEPaste-1	DC.L LEDelete-1	DC.L LEInsert-1	DC.L LEUpdate-1	DC.L LETextBox-1	DC.L LEFromScrap-1	DC.L LEToScrap-1	DC.L LEScrapHandle-1	DC.L LEGetScrapLen-1	DC.L LESetScrapLen-1	DC.L LESetHilite-1	DC.L LESetCaret-1	DC.L LETextBox2-1		; $20 ** added 2-87 Matthew Denman **	DC.L LESetJust-1		; $21 ** added 3-6-87 CAE **	DC.L LEGetTextHand-1 	; $22 ** added 3-24-87 CAE **	DC.L LEGetTextLen-1		; $23 ** added 4-24-87 CAE **	dc.L FakeGetLEDefProc-1	; $24 ** Added 12 Oct 88 SEG*** 6.1	dc.l LEClassifyKey-1	; $25 ** Added 20-Mar-92 DALTheEnd	EndP;****************************************************************;*;* DATA DECLARATIONS;*;****************************************************************;;	EXPORT LEData;LEData	PROC;;	EndP****************************************************************** LEBootInit*****************************************************************	Export LEBootInitLEBootInit	PROC	jmp oStdEnd0	EndP****************************************************************** LEStartUp*****************************************************************	Export LEStartUpLEStartUp	PROC;	cmp #0	;already initialized?	tay	;opt 20-Mar-92 DAL	beq Doit	;no	ldx #InitErr	;yes - so return error	ldy #4	;param size	brl oErrOut	;was jml 19-Sep-90 DALDoit	phd	lda 9,s	;get zero page address	tcd	ldx #$FELoop	stz <LEZBase,x	;clear zero page	dex	dex	bpl Loop	lda 11,s	;get program ID	sta <ProgID	pha	;optimized 19-Sep-90 DAL	pha	PushWord #0	;hi word of size	PushWord #MaxChars	;lo word of size	PushZWord <ProgID	;program ID	PushWord #$0004	;page aligned, unpurgeable	pha	;optimized 19-Sep-90 DAL	pha	_NewHandle	;allocate space for	scrap	bcc GotMem	tax	;xfer error code to	X	pla	;pull result	pla	jmp StdErr4	;return the errorGotMem	pla	sta <ScrapHandle	pla	sta <ScrapHandle+2	lda 9,s	;get zero page address	PushWord #0	PushWord #LETSNum	PushWord #0	pha	_SetWAP	;set work area pointer	jmp StdEnd4	EndP****************************************************************** LEShutDown*****************************************************************	Export LEShutDownLEShutDown	PROC	phd	tcd	bne Doit	ldx #ActiveErr	;return error if Line Edit not active	jmp StdErr0Doit	PushZLong <ScrapHandle	_DisposeHandle	;release scrap space	bcc OK	tax	;xfer error code to	X	jmp StdErr0	;return the errorOK	PushWord #0	PushWord #LETSNum	PushWord #0	PushWord #0	_SetWAP	;clear work area pointer	jmp StdEnd0	EndP****************************************************************** LEVersion*****************************************************************	Export LEVersionLEVersion	PROC	lda #LEVerNum	sta 7,s	jmp oStdEnd0	EndP****************************************************************** LEReset*****************************************************************	Export LEResetLEReset	PROC;	cmp #0	;is LE active?	tay	;opt 20-Mar-92 DAL	beq Done	;no	ldx #ResetErr	;yes - so return error	ldy #0	;param size	brl oErrOut	;was jml 19-Sep-90 DALDone	jmp oStdEnd0	EndP****************************************************************** LEActive*****************************************************************	Export LEActiveLEActive	PROC	sta 7,s	jmp oStdEnd0	EndP****************************************************************** LENew*** Change History** 12 Jun 89	Steven Glass** Fixed bug introduced looking for PW char.  Trying to save* size in x I did a txa rather than a tax.*****************************************************************	Export LENewLENew	PROC	;LENew uses TempPtr1 and TempPtr2	phd	tcd	pha	pha	;optimized 19-Sep-90 DAL	PushWord #0	;hi word of size	PushWord #LERecSize	;lo word of size	PushZWord <ProgID	;prog ID	PushWord #0	;unpurgeable	pha	pha	;optimized 19-Sep-90 DAL	_NewHandle	;allocate mem for the edit record	bcc GotMem	tax	;xfer error code to	X	bra MemErrGotMem	pla	;get handle to mem	sta <RecHandle	;save it	sta 21,s	;and return it	pla	sta <RecHandle+2	sta 21,s	jsr LockRec	lda #0	ldy #LERecSize	dey	deyZLoop	sta [<RecPtr],y	;zero out record	dey	dey	bpl ZLoop	ldy #leMaxLength	lda 9,s	;get maxtextlen parameter	and #$7FFF	cmp #MaxChars	;make sure it's not too big	bcc OK	lda #MaxCharsOK	sta [<RecPtr],y	tax	; save in x for use below   FIXED SEG 12 Jun 89	lda 9,s	; use***	and #$8000***	beq NoPWChar	bpl NoPWChar	;optimized 11-Mar-91 DAL	lda #defaultPWChar	;default pw char is now hollow diamond (11-Mar-91 DAL)***	lda #'*'	ldy #lePWChar	sta [<RecPtr],yNoPWChar	pha	; space for result	pha	PushWord #0	;hi word of size	phx	;lo word of size -	maxtextlen parameter	PushZWord <ProgID	;program ID	PushWord #0	;unpurgeable	pha	; unused long	pha	_NewHandle	;allocate mem for the line	bcc GotMem2	tax	;xfer error code to	X	jsr UnLockRec	;clean upMemErr	pla	;pull result	pla	ldy #10	;param size	brl ErrOut	;return the error (was jml 19-Sep-90 DAL)GotMem2	pla	sta [<RecPtr]	ldy #2	pla	sta [<RecPtr],y	lda 15,s	;get ptr to destrect parameter	sta <TempPtr1	lda 17,s	sta <TempPtr1+2	lda #leDestRect	;create ptr to destrect field and	jsr CopyRect	;copy parameter into field	lda 11,s	;get ptr to viewrect parameter	sta <TempPtr1	lda 13,s	sta <TempPtr1+2	lda #leViewRect	;create ptr to viewrect field and	jsr CopyRect	;copy parameter into field	pha	;optimized 19-Sep-90 DAL	pha	_GetPort	;get handle to current port	ldy #lePort	pla	sta [<RecPtr],y	;and store in port field	iny	iny	pla	sta [<RecPtr],y	PushZPtr <TempPtr1	;push address of TempPtr1	_GetFontInfo	;returns 4 words of	info	clc	lda <TempPtr1	;get ascent	adc <TempPtr2+2	;add in leading	ldy #leBaseHite	sta [<RecPtr],y	;store in basehite field	adc <TempPtr1+2	;add in descent	ldy #leLineHite	sta [<RecPtr],y	;store in linehite field	jsr UnLockRec	ldy #10	;param size	brl EndCall	;was jml 19-Sep-90 DAL;-------------------------------------------------------------------------------CopyRect	clc	adc <RecPtr	;create ptr to field	sta <TempPtr2	lda <RecPtr+2	adc #0	sta <TempPtr2+2	ldy #6RLoop	lda [<TempPtr1],y	;copy parameter into field	sta [<TempPtr2],y	dey	dey	bpl RLoop	rts	EndP****************************************************************** LEDispose*****************************************************************	Export LEDisposeLEDispose	PROC	phd	tcd	lda 9,s	sta <RecHandle	lda 11,s	sta <RecHandle+2	jsr LockRec	ldy #2	lda [<RecPtr],y	;push handle to line	pha	lda [<RecPtr]	pha	jsr UnLockRec	_DisposeHandle	;dispose of line	bcc OK	tax	;xfer error code to	X	jmp StdErr4	;return the errorOK	lda 11,s	;push handle to edit record	pha	lda 11,s	pha	_DisposeHandle	;dispose of edit record	bcc Done	tax	;xfer error code to	X	jmp StdErr4	;return the errorDone	jmp StdEnd4	EndP****************************************************************** LESetText*****************************************************************	Export LESetTextLESetText	PROC	import EraseDestViewGap	phd	tcd	ldx #10	jsr StdEntry;	ldy #leHScrollPos;	lda #0;	sta [<RecPtr],y*** changed 22-Mar-93 DAL to erase the "gap" on the left, if needed	ldy #leHScrollPos	lda [<RecPtr],y	beq @notScrolled	lda #0	sta [<RecPtr],y	jsr EraseDestViewGap@notScrolled*** end 22-Mar-93	lda 13,s	;text length	ldy #leMaxLength	cmp [<RecPtr],y	;is length < max line length?	bcc OK	;yes	lda [<RecPtr],y	;no - so set length	to max line lengthOK	ldy #leLength	sta [<RecPtr],y	ldy #leSelStart	;set insertion point to end of text	sta [<RecPtr],y	ldy #leSelEnd	sta [<RecPtr],y	tay	;transfer text length to Y	beq Done	;quit if length is 0	deyCont	lda 15,s	;get ptr to text	sta <TextPtr	lda 17,s	sta <TextPtr+2;----------------------------------------------------;; Switch to mixed mode (8 bit m) to move the; characters to handle.;;----------------------------------------------------	sep #%00100000	longa offLoop	lda [<TextPtr],y	;copy text into line	sta [<LinePtr],y	dey	bpl Loop	rep #%00100000	longa onDone	jsr StdExit	jmp StdEnd	EndP****************************************************************** LEIdle*****************************************************************	Export LEIdleLEIdle	PROC	phd	tcd	ldx #4	jsr StdEntry	ldy #leCarAct	lda [<RecPtr],y	beq Done	;quit if not active	lda >TickCnt+2	ldy #leCarTime+2	cmp [<RecPtr],y	bcc Done	;quit if hi word of	tickcnt < cartime	bne Time	;branch if tickcnt > cartime	lda >TickCnt	;if hi words equal then check lo words	ldy #leCarTime	cmp [<RecPtr],y	bcc Done	;quit if lo word of	tickcnt < cartimeTime	pha	pha	;optimized 19-Sep-90 DAL	_GetCaretTime	;get # ticks until next blink	ldx #0	;init 'no flash flag' to 0	pla	bne Flash	lda #60	;caret is set to 'no flash' so inc	inx	;CarTime so don't call _GetCaretTime so;		;often and set 'no flash flag'Flash	ldy #leCarTime	clc	;add '# ticks until next blink' to	adc >TickCnt	;current tick count	sta [<RecPtr],y	;and save	iny	iny	pla	adc >TickCnt+2	sta [<RecPtr],y	cpx #0	;check 'no flash flag'	bne Done	;quit if it's set	jsr DrawCaret	;flip the caret	ldy #leCarOn	lda #1	eor [<RecPtr],y	sta [<RecPtr],y	;flip the flagDone	jsr StdExit	jmp StdEnd	EndP****************************************************************** LEClick*****************************************************************	Export LEClickLEClick	PROC	import ComputeMaxScrollPos,EraseDestViewGapEventPtr	equ TempPtr1SaveStart	equ TempPtr2SaveEnd	equ TempPtr2+2	phd	tcd	ldx #8	jsr StdEntry	stz <RevFlag	;clear reversed flag	lda 13,s	;get Event Record pointer	sta <EventPtr	lda 15,s	sta <EventPtr+2	ldy #2	lda [<EventPtr],y	;get button number and save	sta <BNum	ldy #10	lda [<EventPtr],y	;get mouse loc	sta <SelPoint	iny	iny	lda [<EventPtr],y	sta <SelPoint+2	PushZPtr <SelPoint	_GlobalToLocal	;and convert to local coordinates	jsr FindPoint	;returns char index	in SelPoint	bcc GotIndex	jmp Done	;point not in viewrect so quitGotIndex	jsr HideCaret	jsr HiLite	;remove selection	lda <SelPoint	;get current click loc	cmp <ClickLoc	;same loc as previous click?	bne Single	;no - so not a double click;-------------------------------------------------------------------------------; Double Click Stuff	pha	pha	;optimized 19-Sep-90 DAL	_GetDblTime	;get current double	click setting	pla	asl a	;mult by 2 and save	sta <DoubleTime	pla	;discard hi word	sec	ldy #6	lda [<EventPtr],y	;get lo word of click time	sbc <ClickTime	;subtract previous click time	tax	;store in X	iny	iny	lda [<EventPtr],y	;get hi word of click time	sbc <ClickTime+2	;subtract previous click time	bne Single	;if not 0 then too long between clicks	cpx <DoubleTime	;less than double click setting?	bcs Single	;no	lda <DoubleClick	;already had double-click?	bne Triple	;yes - so now have triple click	inc <DoubleClick	;no - so set double	click flag	lda <SelPoint	jsr FindWord	;find word containing selpoint	lda <WordStart	sta <SaveStart	;save wordstart	ldy #leSelStart	sta [<RecPtr],y	;set new selstart	lda <WordEnd	sta <SaveEnd	;save wordend	bra StoreEnd	;set new selend;-------------------------------------------------------------------------------; Triple Click StuffTriple	lda #0	;set selection range to whole line	ldy #leSelStart	sta [<RecPtr],y	ldy #leLength	lda [<RecPtr],y	ldy #leSelEnd	sta [<RecPtr],y	jsr ShowCaret	;** bug fix 2-19-87	CAE **	jsr HiLite	;show new selection;; 4/8/89	mensch; inserted the following loop to troll the event queue for the mouseup that should be; hanging around on the stack@Wait	pha	;optimized 19-Sep-90 DAL	PushZWord <BNum	;button number	_WaitMouseUp	pla	;is button still down?	bne @wait	;yes; END	jmp Done;-------------------------------------------------------------------------------; Single Click StuffSingle	stz <DoubleClick	;clear double click	flag	ldy #14	lda [<EventPtr],y	;get modifiers	and #$0200	;shift key pressed?	bne Extend	;yes - so extend selection	lda <SelPoint	;no - so set insertion point to new loc	ldy #leSelStart	sta [<RecPtr],y	;set new selstart	bra StoreEndExtend	lda <SelPoint	;extend selection to new loc;-------------------------------------------------------------------------------; Save click info and show new insertion point or selection	rangeStoreEnd	ldy #leSelEnd	sta [<RecPtr],y	;set new selend	lda <SelPoint	sta <ClickLoc	;save current click	loc	ldy #6	lda [<EventPtr],y	;get lo word of click time	sta <ClickTime	;and save	iny	iny	lda [<EventPtr],y	;get hi word of click time	sta <ClickTime+2	;and save	jsr ShowCaret	jsr HiLite	;show selection;-------------------------------------------------------------------------------; Check if button still down*** added 22-Jan-92 DAL	jsr ComputeMaxScrollPos*** end 22-Jan-92Wait	pha	;optimized 19-Sep-90 DAL	PushZWord <BNum	;button number	_WaitMouseUp	pla	;is button still down?	bne BtnDown	;yes	jsr ShowCaret	;no - so doneDone	jsr StdExit	jmp StdEnd;-------------------------------------------------------------------------------; Drag StuffBtnDown	PushZPtr <SelPoint	;push ptr to space for result	_GetMouse	;get current mouse position***	jsr FindPoint	;convert to char index***	bcs Wait	;point not in viewrect	lda <SelPoint+2	;14-May-91 DAL	sta <OriginalXPos	;14-May-91 DAL	jsr FindPoint2	;14-May-91 DAL: Don't care if we're in viewRect or not*** 11-Mar-91 DAL -- scroll left or right as necessary*** added 14-Mar-91 DAL--oops, forgot to check if we are left-justified	ldy #leJust	lda [<RecPtr],y	bne @noScrollNeeded	;not left-justified*** end of 14-Mar-91 DAL	ldx #-10	;scroll left this many pixels***	lda <SelPoint+2	;horizontal position	lda <OriginalXPos	;horizontal position, untranslated	ldy #leDestRect+2	cmp [<RecPtr],y	bmi @scrollSome	;scroll to the left	ldx #10	;scroll right this many pixels	ldy #leViewRect+6	cmp [<RecPtr],y	bpl @scrollSome	;scroll to the right	bra @noScrollNeeded@scrollSome	txa	clc	ldy #leHScrollPos	adc [<RecPtr],y	bpl @okay	lda #0@okay	cmp #10000	bcc @okay2	lda #10000@okay2*** added 22-Jan-92 DAL -- clip against MaxScrollPos	cmp <MaxScrollPos	bcc @okay3	lda <MaxScrollPos@okay3*** end 22-Jan-92;;;	sta [<RecPtr],y*** added 22-Jan-92 DAL -- don't flicker if there's no scrolling happening	cmp [<RecPtr],y	sta [<RecPtr],y	beq @noScrollNeeded*** end 22-Jan-92 DAL	jsr EraseDestViewGap  ;22-Jan-92 DAL	stz <DispStart	jsr ReDraw*** Hmmm...is this something close to what I need to do here?  (Apparently!)	jsr ShowCaret	jsr HiLite	;reshow selection	pha	pea 0	;wait from now	pea $0040	;wait 4 ticks	_WaitUntil	pla@noScrollNeeded*** end of 11-Mar-91 DAL	lda <SelPoint	ldy #leSelEnd	cmp [<RecPtr],y	;has mouse moved?***	beq Wait	;no	bne @nowait	brl Wait@nowait	lda <DoubleClick	;was this a double click?	beq DoHilite	;no - so skip some of this stuff	lda <SelPoint	jsr FindWord	;find word containing new mouse loc	lda <SelPoint	cmp <SaveStart	;is selpoint to left of savestart?	bcc OnLeft	;yesOnRight	lda <RevFlag	;is drag direction reversed?	beq GoRight	;no - so OK	lda <SaveStart	;yes - so set selstart to savestart	jsr Reverse	;and reverse direction of drag	stz <RevFlag	;clear reversed flagGoRight	lda <WordEnd	;expand to the right	bra NewPointOnLeft	lda <RevFlag	;is drag direction reversed?	bne GoLeft	;yes - so OK	lda <SaveEnd	;no - so set selstart to saveend	jsr Reverse	;and reverse direction of drag	inc <RevFlag	;set reversed flagGoLeft	lda <WordStart	;expand to the leftNewPoint	sta <SelPointDoHilite	jsr HideCaret	ldy #leSelEnd	lda [<RecPtr],y	sta <DispStart	;dispstart = previous selend	lda <SelPoint	sta <DispEnd	;dispend = new selend	sta [<RecPtr],y	;set new selend	jsr HiLite2	;invert the changed	part	brl Wait	;too far for BRA;-------------------------------------------------------------------------------Reverse	ldy #leSelStart	sta [<RecPtr],y	;set selstart to new value	lda <SaveStart	;invert word the double click was on	sta <DispStart	;so that when we change directions it	lda <SaveEnd	;stays highlighted	sta <DispEnd	jsr HiLite2	rts	EndP****************************************************************** ComputeMaxScrollPos** added 22-Jan-92 DAL -- compute <MaxScrollPos = maximum scroll offset,*  considering current length of the text and width of the destRect.** If textWidth <= destWidth, maxScroll = 0.* If textWidth > destWidth, maxScroll = textWidth - destWidth + slop.** SPECIAL CASE:  If destWidth is zero, maxScroll = 0.  This is*                for AppleWorks GS 1.1 Graphics text items.** Inputs: <RecPtr, <LinePtr* Output: <MaxScrollPos, <DestWidth*****************************************************************ComputeMaxScrollPos	proc export	stz <MaxScrollPos	;anticipate no scrolling allowed	ldy #leDestRect+6	;right edge	lda [<RecPtr],y	sec	ldy #leDestRect+2	sbc [<RecPtr],y	sta <DestWidth	beq @maxScrollZero	;for AWGS!	pha	;space for result	pei <LinePtr+2	;push ptr to text	pei <LinePtr	ldy #leLength	lda [<RecPtr],y	pha	jsl MeasureThisText	pla	;width of current text	cmp <DestWidth	bcc @maxScrollZero	beq @maxScrollZero	sec	sbc <DestWidth	clc	adc #21	;slop	sta <MaxScrollPos@maxScrollZero	rts	EndP*** end 22-Jan-92****************************************************************** LESetSelect*****************************************************************	Export LESetSelectLESetSelect	PROC	import EraseDestViewGap	phd	tcd	ldx #8	jsr StdEntry	jsr HideCaret	jsr HiLite	;remove old selection; The un-scroll code was here, but now it's down below (22-Jan-92 DAL)	lda 15,s	;get new selstart	ldy #leSelStart	sta [<RecPtr],y	;set new selstart	lda 13,s	;get new selend	ldy #leSelEnd	sta [<RecPtr],y	;set new selend*** 11-Mar-91 DAL (moved below HideCaret and HiLite, 14-May-91 DAL)*** (moved below setting selStart and selEnd, 22-Jan-92 DAL)	ldy #leHScrollPos	lda [<RecPtr],y	beq @notScrolled	lda #0	sta [<RecPtr],y	stz <DispStart	jsr ReDraw	jsr EraseDestViewGap@notScrolled*** end of 11-Mar-91 DAL	jsr CleanUpSel	;clean up selection	jsr ShowCaret	jsr HiLite	;show new selection	jsr StdExit	jmp StdEnd	EndP****************************************************************** LEActivate*****************************************************************	Export LEActivateLEActivate	PROC	phd	tcd	ldx #4	jsr StdEntry	ldy #leActFlg	lda [<RecPtr],y	;already active?	bne Done	;yes - so done	lda #1	;no - so set active	flag to true	sta [<RecPtr],y	jsr ShowCaret	;show the caret	jsr HiLite	;show selectionDone	jsr StdExit	jmp StdEnd	EndP****************************************************************** LEDeactivate*****************************************************************	Export LEDeactivateLEDeactivate	PROC	phd	tcd	ldx #4	jsr StdEntry	ldy #leActFlg	lda [<RecPtr],y	;already inactive?	beq Done	;yes - so done	jsr HideCaret	;hide the caret	jsr HiLite	;remove the selection	ldy #leActFlg	lda #0	;set active flag to	false	sta [<RecPtr],yDone	jsr StdExit	jmp StdEnd	EndP****************************************************************** LEKey*****************************************************************	Export LEKeyLEKey	PROC	phd	tcd	ldx #8	jsr StdEntry	_ObscureCursor	;hide cursor	jsr HideCaret	;remove caret	lda 13,s	;get modifiers	sta <Mods	lda 15,s	;get char	sta <TheChar	cmp #$06	;control-F?	beq CntlF	cmp #$18	;control-X?	beq CntlX	cmp #$19	;control-Y?	beq CntlY	cmp #$7F	;backspace?	beq BackSpace	cmp #$08	;left arrow?	beq LArrow	cmp #$15	;right arrow?	beq JmpRArrow	brl DoCharJmpRArrow	brl RArrow	;too far for a branch;-------------------------------------------------------------------------CntlF	jsr CmpSel	;see if null selection range	bne CutIt	;not null, so delete selection;since there's no selection, delete char to the right of the insertion point	ldy #leSelEnd	lda [<RecPtr],y	;get selend	ldy #leLength	cmp [<RecPtr],y	beq JmpDone	;quit if insertion point at end of line	inc a	ldy #leSelEnd	sta [<RecPtr],y	;move selend 1 char	to right	bra CutIt;-------------------------------------------------------------------------CntlX	jsr CmpSel	;see if null selection range	bne CutIt	;not null, so delete selection	lda #0	;is null, so delete	whole line	sta [<RecPtr],y	;set selstart to 0	bra YCont;-------------------------------------------------------------------------CntlY	jsr CmpSel	;see if null selection range	bne CutIt	;not null, so delete selectionYCont	ldy #leLength	;is null, so delete	to end of line	lda [<RecPtr],y	ldy #leSelEnd	sta [<RecPtr],y	;set selend to end of line	bra CutIt;-------------------------------------------------------------------------BackSpace	jsr CmpSel	;see if null selection range	bne CutIt	;not null, so delete selection;since there's no selection, delete char to the left of the insertion point	lda [<RecPtr],y	;get selstart	beq JmpDone	;quit if insertion point at first char	lda [<RecPtr],y	;move selstart 1 char left	dec a	sta [<RecPtr],yCutIt	jsr SelSort	;sort selection ends	jsr SaveStartProc	;save selstart	jsr DeleteGuts	;delete selection	jsr ReDrawJmpDone	jmp Done;--------------------------------------------------------------------LArrow	jsr SaveSel	;save current selection	lda <Mods	and #$0800	;option key pressed?	beq LTstApple	;noLArrow2	ldy #leSelEnd	;yes - so do word selection	lda [<RecPtr],y	;get current selend	beq JmpDone	;quit if at start of line	dec a	;dec by 1 since left arrow	jsr FindWord	;find the word	jsr CmpSel	;already have a selection range?	bne LSelRange	;yes - so branch	lda <WordEnd	;no - so set sel range to the word	sta [<RecPtr],y	;new selstart	tax	;save new selstart in X	lda <Mods	and #$0200	;shift key pressed?	beq LSelRange	;no - so branch	stx <DispStart	;yes-make sure whole word is highlightedLSelRange	ldy #leSelEnd	lda <WordStart	sta [<RecPtr],y	;new selendLCont	lda <Mods	and #$0200	;shift key pressed?	beq LNoShift	;no  - so branch	ldy #leSelStart	;yes - so check if selend and selstart	lda [<RecPtr],y	;are equal	cmp <WordStart	bne LDone	;not equal so done	lda <DispStart	;are equal so set selstart to old selend	sta [<RecPtr],y	;and go back thru previous code to move	jsr SaveSel	;another word to the left	bra LArrow2LTstApple	lda <Mods	and #$0100	;apple key pressed?	beq LTstShift	;no	lda #0	ldy #leSelEnd	sta [<RecPtr],y	;yes - so set selend to start of lineLTstShift	lda <Mods	and #$0200	;shift key pressed?	beq LNoShift	;no	ldy #leSelEnd	lda [<RecPtr],y	beq LDone	;branch if already at start of line	dec a	;extend selection left by 1 char	sta [<RecPtr],y	bra LDoneLNoShift	jsr SelSort	;sort the selection	ends	ldy #leSelStart	lda [<RecPtr],y	beq LCont1	;branch if at start	of line	ldy #leSelEnd	cmp [<RecPtr],y	;is there a selection range?	bne LCont1	;yes - so position at start of selection	dec a	;no - so move insertion point 1 char LLCont1	ldy #leSelStart	sta [<RecPtr],yLCont2	ldy #leSelEnd	sta [<RecPtr],yLDone	lda <Mods	and #$0200	;shift key pressed?	beq LInvert	;no - so branch	ldy #leSelEnd	;yes	lda [<RecPtr],y	;dispend = new selend	sta <DispEndLInvert;;;	jsr HiLite2	;invert part of selection which changed (removed 22-Jan-92 DAL);*** 11-Mar-91 DAL;	jsr ReDraw	;this is overkill;*** end 11-Mar-91 DAL*** 22-Jan-92 DAL -- forcibly redraw everything to cover all cases	stz <DispStart	jsr ReDraw	jsr HiLite*** end 22-Jan-92LJmpDone	jmp Done;--------------------------------------------------------------------RArrow	jsr SaveSel	;save current selection	lda <Mods	and #$0800	;option key pressed?	beq RTstApple	;noRArrow2	ldy #leSelEnd	;yes - so do word selection	lda [<RecPtr],y	;get current selend	ldy #leLength	cmp [<RecPtr],y	beq LJmpDone	;quit if at end of line	jsr FindWord	;find the word	jsr CmpSel	;already have a selection range?	bne RSelRange	;yes - so branch	lda <WordStart	;no - so set sel range to the word	sta [<RecPtr],y	;new selstart	tax	;save new selstart in X	lda <Mods	and #$0200	;shift key pressed?	beq RSelRange	;no - so branch	stx <DispStart	;yes-make sure whole word is highlightedRSelRange	ldy #leSelEnd	lda <WordEnd	sta [<RecPtr],y	;new selend	lda <Mods	and #$0200	;shift key pressed?	beq RNoShift	;no - so branch	ldy #leSelStart	;yes - so  check if	selend and selstart	lda [<RecPtr],y	;are equal	cmp <WordEnd	bne RDone	;not equal so done	lda <DispStart	;are equal so set selstart to old selend	sta [<RecPtr],y	;and go back thru previous code to move	jsr SaveSel	;another word to the right	bra RArrow2RTstApple	lda <Mods	and #$0100	;apple key pressed?	beq RTstShift	;no	ldy #leLength	lda [<RecPtr],y	ldy #leSelEnd	sta [<RecPtr],y	;yes - so set selend to end of lineRTstShift	lda <Mods	and #$0200	;shift key pressed?	beq RNoShift	;no	ldy #leSelEnd	lda [<RecPtr],y	ldy #leLength	cmp [<RecPtr],y	beq RDone	;branch if at end of line	inc a	;extend selection right by 1 char	jmp LCont2RNoShift	jsr SelSort	;sort the selection	ends	ldy #leSelEnd	lda [<RecPtr],y	ldy #leLength	cmp [<RecPtr],y	;already at end of line?	beq RCont1	;yes	ldy #leSelStart	cmp [<RecPtr],y	;is there a selection range?	bne RCont1	;yes - so position at end of selection	inc a	;no - so move insertion point 1 char RRCont1	jmp LCont1RDone	jmp LDone;-------------------------------------------------------------------------SaveSel	ldy #leSelEnd	lda [<RecPtr],y	;dispstart = selend	sta <DispStart	ldy #leSelStart	lda [<RecPtr],y	;dispend = selstart	sta <DispEnd	rts;-------------------------------------------------------------------------DoChar	lda #1	sta <TextLength	stz <TextPtr+2	;set up ptr to char	clc	tdc	adc #TheChar	sta <TextPtr	jsr SelSort	;sort selection ends	jsr HiLite	;remove selection	jsr SaveStartProc	;save selstart	jsr PasteGuts	;insert char	jsr ReDrawDone	jsr ShowCaret	jsr StdExit	jmp StdEnd	EndP****************************************************************** LECut*****************************************************************	Export LECutLECut	PROC	phd	tcd	lda 11,s	;push handle	pha	lda 11,s	pha	jsl xLECopy	;copy selection to scrap	bcs GotErr	lda 11,s	;push handle	pha	lda 11,s	pha	jsl xLEDelete	;delete selection	bcs GotErr	jmp StdEnd4GotErr	tax	;xfer error code to	X	jmp StdErr4	;return the errorxLECopy	tdc	jsl LECopy	rtlxLEDelete	tdc	jsl LEDelete	rtl	EndP****************************************************************** LECopy*** Change History** 16 Jun 88	Steven Glass** Value of scrap length is now checked before moving any data.* this prevents data from being trashed.*****************************************************************	Export LECopyLECopy	PROC	phd	tcd	ldx #4	jsr StdEntry	jsr SelSort	;sort selection ends	jsr CalcSelLen	;calculate length of selection range	sta <ScrapLength	;and store as new scraplength;	cmp #0	; make sure that there is something to move	tay	;opt 20-Mar-92 DAL	beq Done	jsr CalcStartPtr	;StartPtr now points to start of sel	jsr LockScrap	;TextPtr now points	to scrap	ldy <ScrapLength	tya	ror a	bcs DecOne	;branch if length is odd	deyDecOne	deyLoop	lda [<StartPtr],y	;copy selection into scrap	sta [<TextPtr],y	dey	dey	bpl Loop	jsr UnLockScrapDone	jsr StdExit	jmp StdEnd	EndP****************************************************************** LEPaste*****************************************************************	Export LEPasteLEPaste	PROC	phd	tcd	ldx #4	jsr StdEntry	jsr SelSort	;sort selection ends	jsr HideCaret	jsr HiLite	;remove selection	jsr SaveStartProc	;save selstart	jsr LockScrap	;TextPtr now points	to scrap	lda <ScrapLength	sta <TextLength	jsr PasteGuts	;paste scrap into line	jsr UnLockScrap	jsr ReDraw	jsr ShowCaretDone	jsr StdExit	jmp StdEnd	EndP****************************************************************** LEDelete*****************************************************************	Export LEDeleteLEDelete	PROC	phd	tcd	ldx #4	jsr StdEntry	jsr SelSort	;sort selection ends	jsr HideCaret	jsr SaveStartProc	;save selstart	jsr DeleteGuts	;delete the selection	jsr ReDraw	;redraw from saved selstart	jsr ShowCaret	jsr StdExit	jmp StdEnd	EndP****************************************************************** LEInsert*****************************************************************	Export LEInsertLEInsert	PROC	phd	tcd	ldx #10	jsr StdEntry	jsr SelSort	;sort selection ends	jsr HideCaret	jsr HiLite	;remove selection	lda 13,s	ldy #leMaxLength	cmp [<RecPtr],y	;is length > max line length?	bcc OK	;no	lda [<RecPtr],y	;yes - so set it to	max line lengthOK	sta <TextLength	lda 15,s	;get ptr to text to	insert	sta <TextPtr	lda 17,s	sta <TextPtr+2	jsr SaveStartProc	;save selstart	jsr InsertGuts	;insert the text	jsr ReDraw	;redraw from saved selstart	jsr ShowCaret	jsr HiLite	;restore the selectionDone	jsr StdExit	jmp StdEnd	EndP****************************************************************** LEUpdate*****************************************************************	Export LEUpdateLEUpdate	PROC	phd	tcd	ldx #4	jsr StdEntry	jsr HideCaret	;** bug fix 2-24-87	CAE **	stz <DispStart	jsr ReDraw	;redraw from start of line	jsr ShowCaret	;** bug fix 2-24-87	CAE **	jsr HiLite	;reshow selectionDone	jsr StdExit	jmp StdEnd	EndP****************************************************************** LETextBox*****************************************************************	Export LETextBoxLETextBox	PROCRectPtr	equ StartPtrRectWidth	equ TempPtr2NumChars	equ TempPtr2+2H1	equ TempWord1V1	equ TempWord2	phd	tcd	lda #12	;added 22-Sep-90 DAL	sta <stripSize	;added 22-Sep-90 DAL	lda 15,s	;get length of text	bne OK	jmp Done	;quit if 0OK	sta <TextLength	;save text length	lda 11,s	;get ptr to rect and save	sta <RectPtr	lda 13,s	sta <RectPtr+2	lda 17,s	;get ptr to text and save	sta <TextPtr	lda 19,s	sta <TextPtr+2	stz <DispStart	;init char offset to 0	PushWord #0	;space for result	PushWord #0	PushZLong <RectPtr	;destrect	PushZLong <RectPtr	;viewrect - make max text len as small	PushWord #1	;as possible since it won't be used	jsl xLENew	;create a new edit record	bcc OKNew	tax	;xfer error code to	X	pla	;pull result off stack	pla	ldy #12	;# bytes of params for LETextBox	brl ErrOut	;return the error (was jml 19-Sep-90 DAL)OKNew	pla	;get handle to record and save	sta <RecHandle	pla	sta <RecHandle+2	ldx #12	jsr StdEntry2	PushZLong <RectPtr	_EraseRect	;erase the rect	ldy #leDestRect+6	lda [<RecPtr],y	;get H2 of the rect	sec	ldy #leDestRect+2	sbc [<RecPtr],y	;subtract H1 of the	rect	sta <RectWidth	;save width of the rect	lda [<RecPtr],y	;get H1 of the rect	sta <H1	;and save	ldy #leDestRect	lda [<RecPtr],y	;get V1 of the rect	clc	ldy #leBaseHite	adc [<RecPtr],y	;and calculate the base line	sta <V1	;and saveNewLine	clc	lda <TextPtr	;get ptr to start of text	adc <DispStart	;and add current offset	sta <StartPtr	;to calculate ptr to start of line	lda <TextPtr+2	adc #0	sta <StartPtr+2	stz <NumChars	;init '# chars in line' to 0	ldy <DispStart	;get offset to first char in lineLoop	lda [<TextPtr],y	;read the char	iny	;inc char offset	and #$00FF	;mask off the hi byte of the char	cmp #$0D	;is the char a CR?	beq GotCR	;yes	inc <NumChars	;no - so inc '# chars in line'	cpy <TextLength	;are we at the end of the text?	bcc Loop	;no - so check next	charGotCR	sty <DispStart	;save offset to start of next line	lda <NumChars	;get # chars in line	beq NoChars	;branch if no chars	in line	lda 9,s	;get justification	bne NotLeft	PushZWord <H1	;left justified	bra ContNotLeft	pha	;optimized 19-Sep-90 DAL	PushZLong <StartPtr	;ptr to start of line	PushZWord <NumChars	;# of chars in line	_TextWidth	;measure width of line	sec	lda <RectWidth	;get width of rect	sbc 1,s	;subtract width of line	bcs OK2	;branch if linewidth < rectwidth	lda #0OK2	sta 1,s	;save diff between widths	lda 11,s	;get justification	bmi Adjust	;branch if right justify	lda 1,s	;get diff	lsr a	;divide by 2	sta 1,s	;and saveAdjust	pla	;get diff	clc	adc <H1	;add to H1	pha	;and pushCont	PushZWord <V1	_MoveTo	;position pen	PushZLong <StartPtr	;ptr to start of line	PushZWord <NumChars	;# chars in line	_DrawText	;draw the textNoChars	lda <DispStart	;get current char offset	cmp <TextLength	;at end of text?	bcs NoMore	;yes - so done	clc	lda <V1	;get V1 for line just drawn	ldy #leLineHite	adc [<RecPtr],y	;add linehite to calculate V1 for	sta <V1	;next line and save	jmp NewLineNoMore	jsr StdExit	PushZLong <RecHandle	jsl xLEDispose	;dispose of edit record	bcc Done	tax	;xfer error code to	X	jmp StdErr	;LEDispose returned	an errorDone	jmp StdEnd;-------------------------------------------------------------------------------xLENew	tdc	jsl LENew	rtlxLEDispose	tdc	jsl LEDispose	rtl	EndP****************************************************************** LEFromScrap*****************************************************************	Export LEFromScrapLEFromScrap	PROC	phd	tcd	pha	pha	;optimized 19-Sep-90 DAL	PushWord #ScrapType	;type = text	_GetScrapSize	;get size of desk scrap	bcs GotErr	plx	;get lo word of size	pla	;get hi word of size	bne TooBig	;if not 0 then too big	cpx #0	;Check if the desk scrap is empty, if it 	beq Fini	;is there's nothing to copy.	cpx #MaxChars+1	bcc OKTooBig	ldx #DSErr	;error - desk scrap	too big	jmp StdErr0OK	stx <ScrapLength	;new scrap length	pha	pha	;optimized 19-Sep-90 DAL	PushWord #ScrapType	;type = text	_GetScrapHandle	;get handle to desk	scrap	bcc NoErrGotErr	tax	;xfer error code to	X	pla	;pull result	pla	jmp StdErr0	;return the errorNoErr	pla	sta <LineHandle	;save in linehandle	pla	sta <LineHandle+2	jsr LockLine2	;LinePtr now points	to desk scrap	jsr LockScrap	;TextPtr now points	to linedit scrap	ldy <ScrapLength	;get # bytes to copy	tya	ror a	bcs DecOne	;branch if length is odd	deyDecOne	deyLoop	lda [<LinePtr],y	;copy desk scrap into linedit scrap	sta [<TextPtr],y	dey	dey	bpl Loop	jsr UnLockLine	jsr UnLockScrapFini	jmp StdEnd0	EndP****************************************************************** LEToScrap*****************************************************************	Export LEToScrapLEToScrap	PROC	phd	tcd	_ZeroScrap	;zero out desk scrap	jsr LockScrap	;TextPtr now points	to linedit scrap	PushWord #0	;hi word of length	PushZWord <ScrapLength ;lo word of length	PushWord #ScrapType	;type of scrap = text	PushZLong <TextPtr	;ptr to linedit scrap	_PutScrap	;copy linedit scrap	to desk scrap	bcc OK	tax	;xfer error code to	X	jsr UnLockScrap	;clean up	jmp StdErr0	;return the errorOK	jsr UnLockScrap	jmp StdEnd0	EndP****************************************************************** LEScrapHandle*****************************************************************	Export LEScrapHandleLEScrapHandle	PROC	phd	tcd	lda <ScrapHandle+2	;return handle to scrap	sta 11,s	lda <ScrapHandle	sta 9,s	jmp StdEnd0	EndP****************************************************************** LEGetScrapLen*****************************************************************	Export LEGetScrapLenLEGetScrapLen	PROC	phd	tcd	lda <ScrapLength	;return length of scrap	sta 9,s	jmp StdEnd0	EndP****************************************************************** LESetScrapLen*****************************************************************	Export LESetScrapLenLESetScrapLen	PROC	phd	tcd	lda 9,s	;get new scrap length	cmp #MaxChars	;too big?	bcc OK	;no	lda #MaxChars	;yes - so set to max line sizeOK	sta <ScrapLength	ldy #2	;param size	brl EndCall	;was jml 19-Sep-90 DAL)	EndP****************************************************************** LESetHilite*****************************************************************	Export LESetHiliteLESetHilite	PROC	phd	tcd	PushWord #leHiliteHook ;push index to hilitehook field	jmp HookCommon	EndP****************************************************************** LESetCaret*****************************************************************	Export LESetCaretLESetCaret	PROC	phd	tcd	PushWord #leCaretHook ;push index to carethook field	Export HookCommonHookCommon	lda 11,s	sta <RecHandle	;get rec handle	lda 13,s	sta <RecHandle+2	jsr LockRec	;and lock the rec	ply	;get index to correct field	lda 13,s	;store new routine address in field	sta [<RecPtr],y	iny	iny	lda 15,s	sta [<RecPtr],y	jsr UnLockRec	ldy #8	;param size	brl EndCall	;was jml 19-Sep-90 DAL	EndP****************************************************************** LESetJust*****************************************************************	Export LESetJustLESetJust	PROC	;** call added 3-6-87 CAE **	phd	tcd	lda 9,s	sta <RecHandle	;get rec handle	lda 11,s	sta <RecHandle+2	jsr LockRec	;and lock the rec	lda 13,s	;get new text justification	ldy #leJust	sta [<RecPtr],y	;and save in record	jsr UnLockRec	ldy #6	;param size	brl EndCall	;was jml 19-Sep-90 DAL	EndP****************************************************************** LEGetTextHand*****************************************************************	Export LEGetTextHandLEGetTextHand	PROC	;** call added 4-24-87 CAE **	phd	tcd	lda 9,s	sta <RecHandle	;get rec handle	lda 11,s	sta <RecHandle+2	jsr LockRec	;and lock the rec	lda [<RecPtr]	;return handle to line	sta 13,s	ldy #2	lda [<RecPtr],y	sta 15,s	jsr UnLockRec	;unlock the rec	ldy #4	;param size	brl EndCall	;was jml 19-Sep-90 DAL	EndP****************************************************************** LEGetTextLen*****************************************************************	Export LEGetTextLenLEGetTextLen	PROC	;** call added 4-24-87 CAE **	phd	tcd	lda 9,s	sta <RecHandle	;get rec handle	lda 11,s	sta <RecHandle+2	jsr LockRec	;and lock the rec	ldy #leLength	lda [<RecPtr],y	;return length of line	sta 13,s	jsr UnLockRec	;unlock the rec	ldy #4	;param size	brl EndCall	;was jml 19-Sep-90 DAL	EndP****************************************************************** DeleteGuts*****************************************************************	Export DeleteGutsDeleteGuts	PROCSelLength	equ TempWord1MovLength	equ TempWord2EndPtr	equ TempPtr1	jsr CalcSelLen	;calculate length of selection range	beq Done	;quit if length = 0	sta <SelLength	;save length	ldy #leLength	;get length of line	lda [<RecPtr],y	sec	ldy #leSelEnd	;subtract selend to	sbc [<RecPtr],y	;calculate # of chars to move	beq NoMove	;branch if no text to move	sta <MovLength	jsr CalcStartPtr	;StartPtr now points to start of sel	clc	lda <SelLength	;get length of selection	adc <StartPtr	;calculate ptr to end of selection	sta <EndPtr	lda #0	adc <StartPtr+2	sta <EndPtr+2	ldy #0Loop	lda [<EndPtr],y	;move text from end	of selection	sta [<StartPtr],y	;to start of selection thereby deleting	iny	;the selection range	iny	cpy <MovLength	;done with move?	bcc Loop	;noNoMove	ldy #leSelStart	lda [<RecPtr],y	ldy #leSelEnd	sta [<RecPtr],y	;set selend equal to selstart	ldy #leLength	lda [<RecPtr],y	;get length of line	sec	sbc <SelLength	;subtract amount deleted	sta [<RecPtr],y	;save as new lengthDone	rts	EndP****************************************************************** PasteGuts*****************************************************************	Export PasteGutsPasteGuts	PROCSelLength	equ TempWord1Remainder	equ TempWord2	jsr CalcSelLen	;calculate length of selection range	sta <SelLength	;and save	jsr CalcStartPtr	;StartPtr now points to start of sel	ldx <SelLength	;determine whether text length is > or	sec	;< selection length	and load X with the	lda <TextLength	;smaller of the two	sbc <SelLength	bcs Cont	ldx <TextLengthCont	sta <Remainder	;save remainder	txa	;get replace length	back	beq EndLoop	;replace length = 0	ldy #leSelStart	clc	adc [<RecPtr],y	;point selstart to end of replacement	sta [<RecPtr],y	txy	dey	dey	bpl Loop	ldy #0	;replace length = 1	sep #$30	;8 bit mode	lda [<TextPtr],y	sta [<StartPtr],y	rep #$30	;16 bit mode	bra EndLoopLoop	lda [<TextPtr],y	;replace chars in selection with chars	sta [<StartPtr],y	;from scrap	dey	beq Loop	;in case replace length is odd	dey	bpl LoopEndLoop	lda <Remainder	;get remainder back	beq Done	;remainder is 0 so done	bpl DoInsert	;scrap was > selection length	jsr DeleteGuts	;delete remainder of selection	bra DoneDoInsert	clc	lda <TextPtr	;create ptr to remainder of text	adc <SelLength	;which needs to be inserted	sta <TextPtr	lda #0	adc <TextPtr+2	sta <TextPtr+2	lda <Remainder	sta <TextLength	jsr InsertGuts	;insert remaining chars	ldy #leSelStart	lda [<RecPtr],y	ldy #leSelEnd	;set selend equal to selstart	sta [<RecPtr],yDone	rts	EndP****************************************************************** InsertGuts*****************************************************************	Export InsertGutsInsertGuts	PROCOverFlow	equ TempWord1MaxLength	equ TempWord2EndPtr	equ TempPtr1	lda <TextLength	bne Doit	rts	;no text to insert so returnDoit	ldy #leMaxLength	lda [<RecPtr],y	;get max length of line and save	sta <MaxLength	ldy #leSelStart	lda [<RecPtr],y	;get selstart	cmp <MaxLength	;are we at the max length of the line?	bcc Cont	;no	rts	;yes - so returnCont	jsr CalcStartPtr	;StartPtr now points to start of sel	clc	lda [<RecPtr],y	;get selstart	adc <TextLength	;add insert length	dec a	cmp <MaxLength	;overflow ?	bcc OK	;no	sec	;yes - so shorten insert length	lda <MaxLength	;get max line length	sbc [<RecPtr],y	;subtract selstart to get	sta <TextLength	;max amount to insert	lda [<RecPtr],y	;get selstart	ldy #leLength	sta [<RecPtr],y	;as save as line length	bra EndMoveOK	ldy #leLength	clc	lda [<RecPtr],y	;get length of line	and	adc <TextLength	;add insert length to determine final	dec a	;length of line	cmp <MaxLength	;overflow?	bcc OK2	;no	inc a	sec	;yes - so	sbc <MaxLength	;subtract max length of line to	sta <Overflow	;determine amount of overflow	sec	lda [<RecPtr],y	;decrement line length by overflow	sbc <Overflow	;amount so we don't move chars past	sta [<RecPtr],y	;the end of the lineOK2	lda [<RecPtr],y	;get length of line	sec	ldy #leSelStart	;subtract selstart to	sbc [<RecPtr],y	;calculate # chars to move right	beq EndMove	;branch if no text to move	tay	;save # chars to move in Y	clc	;calculate ptr to end of insertion area	lda <StartPtr	adc <TextLength	sta <EndPtr	lda #0	adc <StartPtr+2	sta <EndPtr+2	dey	;# chars to move	dey	bpl MoveLoop	ldy #0	;only move 1 char	sep #$30	;8 bit mode	lda [<StartPtr],y	sta [<EndPtr],y	rep #$30	;16 bit mode	bra EndMoveMoveLoop	lda [<StartPtr],y	;move chars toward end of line to	sta [<EndPtr],y	;make room for insertion	dey	beq MoveLoop	;in case moving odd	# of chars	dey	bpl MoveLoopEndMove	ldy <TextLength	;number of chars to	insert	dey	dey	bpl InsLoop	ldy #0	;insert length = 1	sep #$30	;8 bit mode	lda [<TextPtr],y	sta [<StartPtr],y	rep #$30	;16 bit mode	bra EndInsInsLoop	lda [<TextPtr],y	;insert the text	sta [<StartPtr],y	dey	beq InsLoop	;in case insert length is odd	dey	bpl InsLoopEndIns	ldy #leLength	;adjust line length	by insert amount	jsr Adjust	ldy #leSelStart	;adjust selstart by	insert amount	jsr Adjust	ldy #leSelEnd	;adjust selend by insert amount	jsr Adjust	jsr CleanUpSelDone	rts;-------------------------------------------------------------------------------Adjust	clc	lda [<RecPtr],y	adc <TextLength	sta [<RecPtr],y	rts	EndP****************************************************************** FindPoint*****************************************************************	Export FindPointFindPoint	PROCH1	equ TempWord1Diff	equ TempWord2	pha	;optimized 19-Sep-90 DAL	PushZPtr <SelPoint	;ptr to point where	mouse was clicked	clc	lda <RecPtr	;create ptr to viewrect field	adc #leViewRect	tax	lda <RecPtr+2	adc #0	pha	;and push the ptr	phx	_PtInRect	pla	;is the point in the viewrect?	bne InView	;yes	sec	;no - so set the carry flag	rts	;and returnInView** FindPoint2 entry point always computes <selPoint, as a character* offset, even if the mouse position is outside the view rectangle.** Added 14-May-91 DAL*	export FindPoint2FindPoint2*** 11-Mar-91 DAL -- adjust the point by the leHScroll amount	ldy #leHScrollPos	clc	lda <selPoint+2	adc [<RecPtr],y	sta <selPoint+2*** end 11-Mar-91 DAL	stz <DispStart	ldy #leLength	lda [<RecPtr],y	;get length of line	sta <DispEnd	sta <TextLength	;and save	jsr GetSelRect	;get rect for whole	line	lda <SelRect+2	sta <H1	;save H1 of selrect*** added 14-May-91 DAL -- check vertical position, clip to left or right edges	lda <selPoint	;get V1 of the point	ldy #leViewRect	;compare to V1 of viewRect	cmp [<recPtr],y	bmi clipToLeftEdge	ldy #leViewRect+4	;compare to V2 of viewRect	cmp [<recPtr],y	bpl clipToRightEdge*** end 14-May-91 DAL	lda <SelPoint+2	;get H1 of the point	cmp <SelRect+2	;is it less than H1	of selrect?;;;	bcs CheckR	;no - so check against H2*** 22-Jan-92 DAL -- need a signed compare here	bpl CheckR	;no - so check against H2*** end 22-Jan-92clipToLeftEdge	stz <SelPoint	;yes - so set to first char in line	rtsCheckR	cmp <SelRect+6	;is it greater than	H2 of selrect?	bcc OnChar	;no - so point is on a charclipToRightEdge	ldy #leLength	;yes - so set to last char in line	lda [<RecPtr],y	sta <SelPoint	clc	rtsOnChar	ldy #leViewRect	lda [<RecPtr],y	;get V1 of viewrect	sta <SelRect	;and save as V1 of selrect	ldy #leViewRect+4	lda [<RecPtr],y	;get V2 of viewrect	sta <SelRect+4	;and save as V2 of selrectCont	lda #MaxChars	;get max possible line length to startDiv2	lsr a	;div by 2	cmp <TextLength	;is result <= current line length?	bcs Div2	;no - so divide by 2 again	sta <Diff	;yes - so save;do a binary search	for which character	the mouse point is onLoop	sta <TextLength	pha	;space for result	PushZLong <LinePtr	;push ptr to text	PushZWord <TextLength ;push length to measure	jsl MeasureThisText	clc	pla	;get width of text	adc <H1	;add to H1	sta <SelRect+6	;store in H2	pha	;optimized 19-Sep-90 DAL	PushZPtr <SelPoint	;ptr to point where	mouse was clicked	PushZPtr <SelRect	;ptr to rect for the text we measured	_PtInRect	lsr <Diff	;divide by 2	beq Zero	;if 0, then we've found the char	lda <TextLength	plx	;was the point in the rect?	beq Add	;no - so increase the rect	sec	;yes - so decrease the rect	sbc <Diff	bra LoopAdd	clc	adc <Diff	bra Loop;now that we know which char the point is on, we need to determine whether it's;on the left or right half of the char so we know which side to put the caret onZero	lda 1,s	;check results of last PtInRect call	beq NotIn	;branch if point wasn't in rect	dec <TextLength	;dec char indexNotIn	pha	;optimized 19-Sep-90 DAL	ldy <TextLength	lda [<LinePtr],y	;get char point is on	and #$00FF	;mask off hi byte	pha	;and push	_CharWidth	pla	;get width of char	lsr a	;divide by 2	plx	;get result from last PtInRect call	beq NotIn2	;branch if point wasn't in rect	pha	;save 'char width div 2' on stack	sec	lda <SelRect+6	;get previous H2	sbc 1,s	;and subtract 'char width div 2'	plx	;pull 'char width div 2' from stack	bra Cont2NotIn2	clc	adc <SelRect+6	;add 'char width div 2' to previous H2Cont2	sta <SelRect+6	;save new H2	PushWord #0	;space for result	PushZPtr <SelPoint	PushZPtr <SelRect	_PtInRect	pla	;was the point in the rect?	bne Done	;yes - so it's on the L side so done	inc <TextLength	;no - it's on R side so inc char indexDone	lda <TextLength	sta <SelPoint	;the caret will go on L of this char	clc	rts	EndP****************************************************************** FindWord*****************************************************************	Export FindWordFindWord	PROCxLength	equ TempWord1;		;calling routine sets A to char position	tax	;save char position	ldy #leLength	lda [<RecPtr],y	;get length of line	sta <xLength	;and save	txy	;get position in YLSpaces	lda [<LinePtr],y	;read char	and #$00FF	;mask out hi byte	cmp #$21	;is char a space or	control char?	bcs LChars	;no - so start scanning chars	dey	;yes - so move 1 char to left	bmi LDone	;branch if no more chars on left	bra LSpacesLChars	dey	;move 1 char to left	bmi LDone	;branch if no more chars on left	lda [<LinePtr],y	;read char	and #$00FF	;mask out hi byte	cmp #$21	;is char a space or	control char?	bcs LChars	;no - so check next	charLDone	iny	;skip the space or control char	sty <WordStart	;save current position as wordstart	txy	;get back original char position in YRChars	cpy <xLength	;at end of line?	beq RDone	;yes - so quit	lda [<LinePtr],y	;read char	and #$00FF	;mask out hi byte	cmp #$21	;is char a space or	control char?	bcc RSpaces	;yes - so done scanning chars	iny	;no - so move 1 char to right	bra RChars	;check next charRSpaces	iny	;move 1 char to right	cpy <xLength	;at end of line?	beq RDone	;yes - so quit	lda [<LinePtr],y	;read char	and #$00FF	;mask out hi byte	cmp #$21	;is char a space or	control char?	bcc RSpaces	;yes - so check next charRDone	sty <WordEnd	;save current position as wordend	rts	;done	EndP****************************************************************** ShowCaret*****************************************************************	Export ShowCaretShowCaret	PROC	ldy #leActFlg	lda [<RecPtr],y	;is the edit record	active?	beq Done	;no - so quit	jsr CmpSel	;is selstart = selend?	bne Done	;no - so quit	lda #1	ldy #leCarAct	sta [<RecPtr],y	;activate caret	ldy #leCarOn	lda [<RecPtr],y	;get status of caret	bne Done	;quit if caret already on	lda #1	sta [<RecPtr],y	;mark caret as on	jmp DrawCaret	;force a redrawDone	rts	EndP****************************************************************** HideCaret*****************************************************************	Export HideCaretHideCaret	PROC	ldy #leActFlg	lda [<RecPtr],y	beq Done	;quit if edit record not active	ldy #leCarAct	lda #0	sta [<RecPtr],y	;deactivate caret	ldy #leCarOn	lda [<RecPtr],y	beq Done	;quit if caret not on	lda #0	sta [<RecPtr],y	;mark caret as off	jmp DrawCaret	;force a redrawDone	rts	EndP****************************************************************** DrawCaret*****************************************************************	Export DrawCaretDrawCaret	PROC	ldy #leSelStart	lda [<RecPtr],y	;get selstart	sta <DispStart	;and save as dispstart	sta <DispEnd	;and dispend	jsr GetSelRect	;get rect with H1 =	H2	jsr AdjustSelRectH	;11-Mar-91 DAL	inc <SelRect+6	;increment H2 to make space for caret	ldy #leCaretHook+2	jsr InvertHook	;invert the rect	rts*** 11-Mar-91 DAL: adjust the rectangle by leHScrollPos	export AdjustSelRectHAdjustSelRectH	ldy #leHScrollPos	lda <SelRect+2	;first adjust the left edge	sec	sbc [<RecPtr],y	sta <SelRect+2	lda <SelRect+6	;and now adjust the right edge	sec	sbc [<RecPtr],y	sta <SelRect+6	rts*** end of 11-Mar-91 DAL	EndP****************************************************************** HiLite*****************************************************************	Export HiLiteHiLite	PROC	ldy #leActFlg	lda [<RecPtr],y	bne Doit	rts	;quit if edit record not activeDoit	ldy #leSelStart	lda [<RecPtr],y	;get selstart and save as dispstart	sta <DispStart	ldy #leSelEnd	lda [<RecPtr],y	;get selend and save as dispend	sta <DispEnd	Export HiLite2HiLite2	jsr GetSelRect	;get rect from dispstart to dispend*** added 14-May-91 DAL	pei <SelRect+6	pei <SelRect+2	jsr AdjustSelRectH	;added 14-May-91 DAL*** end	ldy #leHiliteHook+2	jsr InvertHook	;invert the rect*** added 14-May-91 DAL	pla	sta <SelRect+2	pla	sta <SelRect+6*** end	rts	EndP****************************************************************** InvertHook*****************************************************************	Export InvertHookInvertHook	PROC	PushZPtr <SelRect	;push ptr to selrect on stack	lda [<RecPtr],y	;Y was set in calling routine to	dey	;#leHiliteHook+2 or	#leCaretHook+2	dey	ora [<RecPtr],y	;does hook contain an address?	bne UseHook	;yes - so use it	_InvertRect	;no - so use InvertRect	rtsUseHook	jsl Kludge	;force a long return address on stack	rts	;hook routine will RTL here;Kludge	sec	;push hook address - 1 on stack;	lda [<RecPtr],y;	sbc #1;	tax;	iny;	iny;	lda [<RecPtr],y;	sbc #0;;	sep #$20	;8 bit A;	pha	;hi byte of hook address;	rep #$20	;16 bit A;;	phx	;lo word of hook address;	rtl	;fake a JSL to the hook routine** New dispatch-to-hook routine 14-May-91 DAL** Note that it is WRONG to decrement the bank byte of* an address to be RTLed to, since RTL never increments* the bank byte (the PC does not wrap to the next bank).*Kludge	lda [<RecPtr],y	tax	dex	;low word of address, decremented by one	iny	iny	lda [<RecPtr],y	sep #$20	pha	;high byte of address, never decrement!	rep #$20	phx	rtl	EndP****************************************************************** ReDraw******************************************************************* 11-Mar-91 DAL** Notes on existing code:*   1. For left-justify, <dispStart must be set up before ReDraw*      is called.*   2. DispStart is the character offset of the leftmost character*      that we have to redraw.*****************************************************************	Export ReDrawReDraw	PROC;** ReDraw modified	3-6-87 to handle centered and right-justified text. CAE **	ldy #leJust	lda [<RecPtr],y	;check the text justification	beq ItsLeft	;branch if left justified	stz <DispStart	;zero out DispStartItsLeft		;DispStart set up by calling routine	jsr CalcHScrollPos	;11-Mar-91 DAL	bcc @noErase	;don't redraw, no change! (22-Jan-92 DAL)	jsr EraseDestViewGap  ;subroutinized 22-Jan-92 DAL@noErase	lda <DispStart	;want H1 and H2 of SelRect to be the	sta <DispEnd	;same	jsr GetSelRect	ldy #leViewRect+6	;set H2 of SelRect equal to H2 of the	lda [<RecPtr],y	;ViewRect	sta <SelRect+6*** added 14-May-91 DAL -- offset the off-the-right-edge rectangle for scrolling	pei <SelRect+2	sec	lda <SelRect+2	ldy #leHScrollPos	sbc [<RecPtr],y	sta <SelRect+2*** end 14-May-91 DAL	PushZPtr <SelRect	;push ptr to SelRect	_EraseRect	;erase from dispstart to end of viewrect	pla	;14-May-91 DAL	sta <SelRect+2	;14-May-91 DAL	ldy #leJust	lda [<RecPtr],y	;check the text justification again	beq ItsLeft2	;branch if left justified	jsr SpecialJust	;handle centered or	right justifiedItsLeft2		;	pei <SelRect+2	;H1 (optimized 11-Mar-91 DAL; was LDA/PHA)	lda <SelRect	;V1 - top of dest rect	clc	ldy #leBaseHite	adc [<RecPtr],y	;calculate base line for text	pha	_MoveTo	;position pen*** 11-Mar-91 DAL: move pen left by leHScrollPos pixels	ldy #leHScrollPos	lda [<RecPtr],y	eor #$ffff	inc a	pha	pea 0	_Move*** end 11-Mar-91 DAL	ldy #leLength	;calculate length of text to draw	lda [<RecPtr],y	sec	sbc <DispStart	beq Done	;quit if no text to	draw	tay	;save length in Y	clc	;calculate ptr to text to be drawn	lda <LinePtr	adc <DispStart	tax	lda <LinePtr+2	adc #0	pha	;push ptr to text	phx	phy	;push length of text	jsl DrawThisTextDone	rts****************************************************************** EraseDestViewGap** Erase the gap on the left between the destRect and viewRect.*****************************************************************	export EraseDestViewGapEraseDestViewGap*** added 14-May-91 DAL -- erase the rect between view and dest on the left	ldy #leJust	lda [<RecPtr],y	bne @noSlopRect	;do this for left-justified only	pei <DispStart	;preserve	stz <DispStart	stz <DispEnd	jsr GetSelRect	ldy #leViewRect+2	;left edge of viewRect	lda [<RecPtr],y	sta <SelRect+2	;set left edge of temp rect	pushzptr <SelRect	ldy #leHScrollPos	lda [<RecPtr],y	eor #$ffff	inc a	pha	;delta x = - leHScrollPos	pea 0	;delta y	_OffsetRect	pushzptr <SelRect	_EraseRect	pla	sta <DispStart	;restore@noSlopRect	rts*** end of 14-May-91 DAL****************************************************************** CalcHScrollPos -- new routine 11-Mar-91 DAL** Called by ReDraw before it does much.** Compute a new value for this line edit record's leHScrollPos field,* if necessary.** If we change the leHScrollPos value, then we need to zero out DispStart* so that all the text gets redrawn** Out: CLC = no change in leHScroll, SEC = change*****************************************************************CalcHScrollPos	ldy #leJust	lda [<RecPtr],y	bne @exit	;we only care about left-justify	jsr CalcNewHScroll	bcs @exit	ldy #leHScrollPos	cmp [<RecPtr],y	beq @exit	sta [<RecPtr],y	stz <DispStart	sec	;added 22-Jan-92 DAL -- flag a change	rts@exit	clc	;added 22-Jan-92 DAL -- flag no-change	rts** Return CLC, A=new leHScroll value*CalcNewHScroll*** added 22-Jan-92 DAL -- if destRect width is 0, return scroll pos zero (for AWGS 1.1 graphics)	ldy #leDestRect+6	lda [<RecPtr],y	ldy #leDestRect+2	sec	sbc [<RecPtr],y	bne @continue	clc	rts	;return clc, A=0@continue*** end 22-Jan-92*** If selStart<>selEnd, then we don't care about the scroll position	ldy #leSelStart	lda [<RecPtr],y	ldy #leSelEnd	cmp [<RecPtr],y	bne @exit*** If MeasureText(0..selStart) - leHScrollPos is out of range, bring it*** back into range.	pha	;space for result	pei <LinePtr+2	;push ptr to text	pei <LinePtr	pha	;selStart value	jsl MeasureThisText	pla	;pixel offset of insertion point	tax	sec	ldy #leHScrollPos	sbc [<RecPtr],y	bcc @outOfRange	;are we outside destRect to the left?	pha	ldy #leDestRect+6	lda [<RecPtr],y	ldy #leDestRect+2	sec	sbc [<RecPtr],y	;A=width of destRect	tay	cmp 1,s	pla	bcc @outOfRange	sec	;old scroll position is fine	rts*** out of range--calculate new leHScrollPos value (X=width of text, Y=width of dest rect)@outOfRange	txa	phy	sec	sbc 1,s	ply	clc	adc #10	bpl @okay	lda #0@okay	clc	rts@exit	sec	rts;-------------------------------------------------------------------------------;Text is centered or right-justified.SpecialJust	pha	;save justification	for later	ldy #leLength	lda [<RecPtr],y	;get new text length	tax	PushWord #0	;space for result	PushZLong <LinePtr	;push ptr to line	phx	;push length to measure	jsl MeasureThisText	sec	;calculate width of	current DestRect	ldy #leDestRect+6	;which gives us the	width of the	lda [<RecPtr],y	;previous text	ldy #leDestRect+2	sbc [<RecPtr],y	cmp 1,s	;compare it to width of new text	bcc GrowRect;New text is smaller than previous text	so DestRect must shrink.ShrinkRect	sbc 1,s	;calculate difference in widths	sta 1,s	;and save	lda 3,s	;check text justification	bmi Right	lda 1,s	;it's centered so divide width	lsr a	;difference by 2	sta 1,s	;and saveRight		;	clc	;move left side of DestRect to right	ldy #leDestRect+2	lda [<RecPtr],y	adc 1,s	sta [<RecPtr],y	sta <SelRect+2	lda 3,s	;check justification	bmi ShrinkDone	;it's right just - so skip next part	sec	;move right side of	DestRect to left	ldy #leDestRect+6	lda [<RecPtr],y	sbc 1,s	sta [<RecPtr],yShrinkDone	pla	;clean up stack	pla	rts;New text is larger	than previous text so DestRect must grow.GrowRect	pha	;save width of previous text	sec	lda 3,s	sbc 1,s	;calculate difference in widths	sta 3,s	;and save	pla	lda 3,s	;check text justification	bmi Right2	lda 1,s	;it's centered so divide width	lsr a	;difference by 2	sta 1,s	;and saveRight2		;	sec	;move left side of DestRect to left	ldy #leDestRect+2	lda [<RecPtr],y	sbc 1,s	sta [<RecPtr],y	sta <SelRect+2	lda 3,s	;check justification	bmi GrowDone	;it's right just - so skip next part	clc	;move right side of	DestRect to right	ldy #leDestRect+6	lda [<RecPtr],y	adc 1,s	sta [<RecPtr],yGrowDone	pla	;clean up stack	pla	rts	EndP*****************************************************************DrawThisText	PROC** This routine draws the indicated text or an equal number* of password characters.** Routine is called with a JSL*** Inputs:*	PtrToText : LONG*	TextLength : word** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	DefineStackRtlAddr	block 3ThisTextLen	wordThisTextPtr	long;; See if programmer wants this treated as password;	ldy #lePWChar	lda [<RecPtr],y	bne ThisIsPassword	ldx #$A704	; DrawText	jsl $E10004	; THROUGH GLUE ENTRY!	rtl;; This is a password, so draw the pw char only.;ThisIsPassword	tax	lda ThisTextLen,s	sta MeasureTemp	jsr PushCharOnStack	tsc	inc a	pea 0000	pha	pei MeasureTemp	_DrawText	lda MeasureTemp	jsr PullCharOffStack	lda RTLAddr,s	sta RTLAddr+6,s	lda RTLAddr+1,s	sta RTLAddr+1+6,s	pla	pla	pla	rtl	ENTRY PushCharOnStackPushCharOnStack;	cmp #0	tay	;opt 20-Mar-92 DAL	bne @NotZero	rts@NotZero;	tay	; put length in y	txa	; put char in a-reg	plx	; pull off rts addr	sep #$20	; 8 bit a-reg	longa off	@PushLoop	pha	; push these on stack	dey	bne @PushLoop	rep #$20	longa on	phx	rts	ENTRY PullCharOffStackPullCharOffStack;	cmp #0	tay	;opt 20-Mar-92 DAL	bne @NotZero	rts@NotZero;	tay	; put length in y	txa	; put char in a-reg	plx	; pull off rts addr	sep #$20	; 8 bit a-reg	longa off	@PushLoop	pla	; push these on stack	dey	bne @PushLoop	rep #$20	longa on	phx	rts		EndP*****************************************************************MeasureThisText	PROC** This routine measures the indicated text or an equal number* of password characters.** Routine is called with a JSL*** Inputs:*	Space for result : word*	PtrToText : LONG*	TextLength : word** Outputs:*	Pixels wide : word** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	DefineStackRtlAddr	block 3ThisTextLen	wordThisTextPtr	longThisTextWidth	word;; See if programmer wants this treated as password;	ldy #lePWChar	lda [<RecPtr],y	bne ThisIsPassword	ldx #$AB04	; TextWidth	jsl $E10004	; through GLUE ENTRY!	rtl;; This is a password, so draw the pw char only.;ThisIsPassword	tax	lda ThisTextLen,s	sta MeasureTemp	jsr PushCharOnStack	tsc	inc a	pha	pea 0000	pha	pei MeasureTemp	_TextWidth	lda MeasureTemp	plx	stx MeasureTemp	jsr PullCharOffStack	lda MeasureTemp	sta ThisTextWidth,s	lda RTLAddr,s	sta RTLAddr+6,s	lda RTLAddr+1,s	sta RTLAddr+1+6,s	pla	pla	pla	rtl	EndP****************************************************************** GetSelRect*****************************************************************	Export GetSelRectGetSelRect	PROC;calculate rect from dispstart to dispend and save in SelRect	lda <DispStart	cmp <DispEnd	;is dispstart < dispend?	bcc OK	;yes	ldx <DispEnd	;no - so swap them	sta <DispEnd	stx <DispStartOK	ldy #leDestRect	lda [<RecPtr],y	;get V1 of destrect	sta <SelRect	;and save as V1 of selrect	ldy #leLineHite	clc	adc [<RecPtr],y	;then add linehite to V1	sta <SelRect+4	;and save as V2 of selrect	ldy #leDestRect+2	lda [<RecPtr],y	;get H1 of destrect	sta <SelRect+2	;and save as H1 of selrect	lda <DispStart	;if dispstart is 0,	skip next section	beq Cont	PushWord #0	;space for result	PushZLong <LinePtr	;push ptr to line	PushZWord <DispStart ;push length to measure	jsl MeasureThisText	;measure from start	of line to dispstart	pla	;get text width	clc	adc <SelRect+2	;add H1 of destrect	sta <SelRect+2	;and save as H1 of selrectCont	lda <DispEnd	cmp <DispStart	;dispend = dispstart?	bne Cont1	;no - so measure	lda <SelRect+2	;yes - so set H2 to	H1	bra DoneCont1	PushWord #0	;space for result	PushZLong <LinePtr	;push ptr to line	PushZWord <DispEnd	;push length to measure	jsl MeasureThisText	;measure from start	of line to dispend	pla	;get text width	ldy #leDestRect+2	clc	adc [<RecPtr],y	;add H1 of destrectDone	sta <SelRect+6	;and save as H2 of selrect	rts	EndP****************************************************************** SaveStartProc*****************************************************************	Export SaveStartProcSaveStartProc	PROC	ldy #leSelStart	lda [<RecPtr],y	;get selstart and save as	sta <DispStart	;dispstart (will be	used by ReDraw)	rts	EndP****************************************************************** CalcStartPtr*****************************************************************	Export CalcStartPtrCalcStartPtr	PROC	clc	ldy #leSelStart	lda [<RecPtr],y	;get selstart	adc <LinePtr	;calculate ptr to start of selection	sta <StartPtr	;and save in StartPtr	lda #0	adc <LinePtr+2	sta <StartPtr+2	rts	;return with Y = leSelStart	EndP****************************************************************** CalcSelLen*****************************************************************	Export CalcSelLenCalcSelLen	PROC	ldy #leSelEnd	;calculate length of selection range	lda [<RecPtr],y	sec	ldy #leSelStart	sbc [<RecPtr],y	rts	;return length in A	EndP****************************************************************** CmpSel*****************************************************************	Export CmpSelCmpSel	PROC	ldy #leSelEnd	lda [<RecPtr],y	ldy #leSelStart	cmp [<RecPtr],y	;compare selstart and selend and	rts	;return with Y = leSelStart	EndP****************************************************************** SelSort*****************************************************************	Export SelSortSelSort	PROC	jsr CmpSel	;is selend >= selstart?	bcs OK	;yes - so OK	tax	;no - so swap them,	 save selend in X	lda [<RecPtr],y	;get selstart and push on stack	pha	txa	;get selend back in	A	sta [<RecPtr],y	;and save in selstart	ldy #leSelEnd	pla	;get selstart off stack	sta [<RecPtr],y	;and save in selendOK	rts	EndP****************************************************************** CleanUpSel*****************************************************************	Export CleanUpSelCleanUpSel	PROC	ldy #leLength	lda [<RecPtr],y	;get line length	ldy #leSelEnd	cmp [<RecPtr],y	;is length >= selend ?	bcs EndOK	;yes	sta [<RecPtr],y	;no - so set selend	to lengthEndOK	lda [<RecPtr],y	;get selend	ldy #leSelStart	cmp [<RecPtr],y	;is selend >= selstart ?	bcs StartOK	;yes	sta [<RecPtr],y	;no - so set selstart to selendStartOK	rts	EndP****************************************************************** StdEnd*****************************************************************	Export StdEndStdEnd	PROC	ldy <StripSize	;# bytes of param to strip	brl EndCall	;was jml 19-Sep-90 DAL	EndP****************************************************************** StdErr*****************************************************************	Export StdErrStdErr	PROC	ldy <StripSize	;# bytes of param to strip	jml ErrOut	EndP****************************************************************** oStdEnd0*****************************************************************	Export oStdEnd0oStdEnd0	PROC	ldy #0	;# bytes of param to strip	brl oEndCall	;was jml 19-Sep-90 DAL	EndP****************************************************************** StdEnd0*****************************************************************	Export StdEnd0StdEnd0	PROC	ldy #0	;# bytes of param to strip	brl EndCall	;was jml 19-Sep-90 DAL	EndP****************************************************************** StdErr0*****************************************************************	Export StdErr0StdErr0	PROC	ldy #0	;# bytes of param to strip	jml ErrOut	EndP****************************************************************** StdEnd4*****************************************************************	Export StdEnd4StdEnd4	PROC	ldy #4	;# bytes of param to strip	jml EndCall	EndP****************************************************************** StdErr4*****************************************************************	Export StdErr4StdErr4	PROC	ldy #4	;# bytes of param to strip	jml ErrOut	EndP****************************************************************** StdEntry*****************************************************************	Export StdEntryStdEntry	PROC	lda 11,s	;get rec handle	sta <RecHandle	lda 13,s	sta <RecHandle+2	Export StdEntry2StdEntry2	stx <StripSize	;save # bytes of param to strip later	stz <ErrFlag	;clear error count	jsr LockRec	;lock rec handle and convert to ptr	jsr LockLine	;lock line handle and convert to ptr	pha	pha	;optimized 19-Sep-90 DAL	_GetPort	;get current port	pla	;and save	sta <SavePort	pla	sta <SavePort+2	ldy #lePort+2	;set to our port	lda [<RecPtr],y	pha	dey	dey	lda [<RecPtr],y	pha	_SetPort	pha	pha	;optimized 19-Sep-90 DAL	_NewRgn	;make room for clip	info	bcc OK	plx	;pull result	plx	pha	;save error code on	stack	inc <ErrFlag	;inc error count	jmp CExit	;clean upOK	lda 1,s	sta <SaveClip	lda 3,s	sta <SaveClip+2	_GetClip	;save current clip	bcc OK2	pha	;save error code on	stack	inc <ErrFlag	;inc error count	jmp BExit	;clean upOK2	clc	;push ptr to viewrect	lda <RecPtr	adc #leViewRect	tax	lda <RecPtr+2	adc #0	pha	phx	_ClipRect	;set clip to viewrect	bcs GotErr	PushZLong <SaveClip	;push saved clip	pha	pha	;optimized 19-Sep-90 DAL	_GetClipHandle	;get our clip - leave on stack	lda 3,s	;our clip will be destination also	pha	lda 3,s	pha	_SectRgn	;intersect saved clip and our clip	bcc DoneGotErr	pha	;save error code on	stack	inc <ErrFlag	;inc error count	jmp AExit	;clean upDone	rts	EndP****************************************************************** StdExit*****************************************************************	Export StdExitStdExit	PROC	stz <ErrFlag	;clear error count	Export AExitAExit	PushZLong <SaveClip	_SetClip	;restore original clip	bcc BExit	pha	;save error code on	stack	inc <ErrFlag	;inc error count	Export BExitBExit	PushZLong <SaveClip	_DisposeRgn	;dispose of our copy of original clip	bcc CExit	pha	;save error code on	stack	inc <ErrFlag	;inc error count	Export CExitCExit	PushZLong <SavePort	_SetPort	;restore original port	jsr UnLockLine	jsr UnLockRec	lda <ErrFlag	;check error count	bne GotErr	;got an error	rts	;no error so returnGotErr	plx	;pull error code off stack	dec a	;dec error count	bne GotErr	;branch if more error codes on stack	pla	;pull return address off stack	jmp StdErr	;return the error	EndP****************************************************************** LockRec*****************************************************************	Export LockRecLockRec	PROC	ldy #4	lda [<RecHandle],y	ora #$8000	;set locked bit in attribute word	sta [<RecHandle],y	ldy #2	lda [<RecHandle]	;dereference handle	sta <RecPtr	lda [<RecHandle],y	sta <RecPtr+2	rts	EndP****************************************************************** UnLockRec*****************************************************************	Export UnLockRecUnLockRec	PROC	ldy #4	lda [<RecHandle],y	and #$7FFF	;clear locked bit in attribute word	sta [<RecHandle],y	rts	EndP****************************************************************** LockLine*****************************************************************	Export LockLineLockLine	PROC	lda [<RecPtr]	sta <LineHandle	ldy #2	lda [<RecPtr],y	sta <LineHandle+2	Export LockLine2LockLine2	ldy #4	lda [<LineHandle],y	ora #$8000	;set locked bit in attribute word	sta [<LineHandle],y	ldy #2	lda [<LineHandle]	;dereference handle	sta <LinePtr	lda [<LineHandle],y	sta <LinePtr+2	rts	EndP****************************************************************** UnLockLine*****************************************************************	Export UnLockLineUnLockLine	PROC	ldy #4	lda [<LineHandle],y	and #$7FFF	;clear locked bit in attribute word	sta [<LineHandle],y	rts	EndP****************************************************************** LockScrap*****************************************************************	Export LockScrapLockScrap	PROC	ldy #4	lda [<ScrapHandle],y	ora #$8000	;set locked bit in attribute word	sta [<ScrapHandle],y	ldy #2	lda [<ScrapHandle]	;dereference handle	sta <TextPtr	lda [<ScrapHandle],y	sta <TextPtr+2	rts	EndP****************************************************************** UnLockScrap*****************************************************************	Export UnLockScrapUnLockScrap	PROC	ldy #4	lda [<ScrapHandle],y	and #$7FFF	;clear locked bit in attribute word	sta [<ScrapHandle],y	rts	EndP			PRINT PUSH	PRINT NOWARN****************************************************************** LETextBox2*** Change History** 05 Aug 88	STeven Glass** If bounding box was bad, we just exit, but check was made* after handle allocated.  We move the check up and this* should make prevent the orphaning of the handle.** The error code was not preserved through the code that* restores the grafport.*****************************************************************	Export LETextBox2LETextBox2	PROC	;** modified 4-22-87 CAE **;-----------------------------------------------------------;; DirectPage;;-----------------------------------------------------------MyId	equ 92LastPartChar	equ 96LastFullChar	equ LastPartChar+2ClipRgn	equ LastFullChar+2LEZero	equ ClipRgn+4LastLeading	equ LEZero+2MaxLine	equ LastLeading+2TempPtr	equ MaxLine+2;;;TempTP	equ TempPtr+4	;was for Equal-tempered stuff;;;TempTL	equ TempTp+4	;was for Equal-tempered stuffChange	equ TempPtr+4	;was TempTL+2 (22-Aug-91 DAL)Skiping	equ Change+2changeflg	equ Skiping+2TextRgn	equ changeflg+2BoxRgn	equ TextRgn+4FontInfoPtr	equ BoxRgn+4FontInfoRec	equ FontInfoPtr+4;;;FontGlobals	equ FontInfoRec+8	;removed 22-Aug-91 DALSpaces	equ FontInfoRec+8	;was FontGlobals+4CurrentSpaces	equ Spaces+2TokenLength	equ CurrentSpaces+2MaxWidth	equ TokenLength+2CharLine	equ MaxWidth+2CurrentWidth	equ CharLine+2Temp	equ CurrentWidth+2Tabs	equ Temp+2Nothing	equ Tabs+2TERec	equ Nothing+2TERuler	equ TERec+4LineStyle	equ TERuler+2;;;FGHandle	equ LineStyle+2	;removed 22-Aug-91 DALLineRuler	equ LineStyle+2	;was FGHandle+4Char	equ LineRuler+4OffSet	equ Char+2InputDone	equ Offset+2LineDone	equ InputDone+2MaxHeight	equ LineDone+2CurrentHeight	equ MaxHeight+2CRFlag	equ CurrentHeight+2OrigDirect	equ CRFlag+2RTL1	equ OrigDirect+2RTL2	equ RTL1+3TextJust	equ RTL2+3TextRectPtr	equ TextJust+2TextLen	equ TextRectPtr+4TextPtr	equ TextLen+2GotFChange	equ TextPtr+4theFontGlobals	equ GotFChange+2	;added 22-Aug-91 DAL: 14 bytesPrintedSomeChars	equ theFontGlobals+14  ;added 4-Sep-91 DAL: wordoldCurrentHeight	equ PrintedSomeChars+2 ;added 4-Sep-91 DAL: word;--------------------------------------------------------------------;; TERecord;;--------------------------------------------------------------------TEPtr	equ 0TELen	equ TEPtr+4DestRect	equ TELen+2ViewRect	equ DestRect+4SelRect	equ ViewRect+4SelPoint	equ SelRect+4SelStart	equ SelPoint+4SelEnd	equ SelStart+2InPort	equ SelEnd+2ClickTime	equ InPort+4ClickLoc	equ ClickTime+4caretTime	equ ClickLoc+2CaretState	equ ClickTime+4RecalBack	equ CaretState+2RecalLines	equ RecalBack+2ClickStuff	equ RecalLines+2ClickLoop	equ ClickStuff+2WordBreak	equ ClickLoop+4HighHook	equ WordBreak+4CaretHook	equ HighHook+4TabHook	equ CaretHook+4AutoIndent	equ TabHook+4NLines	equ AutoIndent+4LSPTR	equ NLines+2LHPtr	equ LSPtr+4;TERulerFGroundColor	equ 0BGroundColor	equ FGroundColor+2FamNum	equ BGroundColor+2SizeStyle	equ FamNum+2Just	equ SizeStyle+2CROnly	equ Just+2LeftMargin	equ CROnly+2RightMargin	equ LeftMargin+2ExtraSpacing	equ RightMargin+2;;;EQTemperedLS	equ ExtraSpacing+2	;Q change not fully	implemented! (rmv 22-Aug-91 DAL);;;SInvis	equ EQTemperedLS+2	;SInvis not used (22-Aug-91 DAL);;;NextRuler	equ SInvis+2NextRuler	equ ExtraSpacing+2	;22-Aug-91 DAL;--------------------------------------------------------------------;DataDeltaFlg	equ $01S	equ $53F	equ $46Z	equ $5AB	equ $42C	equ $43J	equ $4AL	equ $4CM	equ $4DR	equ $52X	equ $58Q	equ $51; Overlay my parameters with the direct	page	phd	;save direct page	tcd	;set the direct page;I now have storage	for variables and a	new direct page	pla	sta OrigDirect	pla	sta rtl1	pla	sta rtl1+2	pla	sta rtl1+4	pla	sta TextJust	pla	sta TextRectPtr	pla	sta TextRectPtr+2	pla	sta TextLen	pla	sta TextPtr	pla	sta TextPtr+2;-----------------------------------------------------------;; Now that stack is cleaned off I must save parts of the ; grafPort that may be changed.;	phb	; save the dbr	pha	; get current port ptr	pha	_GetPort	lda 2,s	; set dbr to bank of port	pha	plb	plb	plx	; put ptr in x	pla	; ignore high word	ldy #opicSave-ofontHandle-2	; use this as count@1	lda |ofontHandle,x	; read the words from the grafport	pha	; and put them on the stack	inx	inx	dey	dey	bpl @1	; repeat until y < 0;---------------------------------------------------------------;; LegalRect;; Quit's Textbox if passed an illegal rect.;; Moved this code in front of code that does new handle; so when it exits, there is not handle to dispose.;	lda [TextRectPtr]	ldy #4	cmp [TextRectPtr],y	bpl aBadRect	ldy #2	lda [TextRectPtr],y	ldy #6	cmp [TextRectPtr],y	bmi RectOKaBadRect	brl Exit	;It's illegal so quit.RectOK;--------------------------------------------------------------;;TENew;;Get a new handle or memory for the TERecord, and set it up.;TENew	pha	pha	;space for result	PushLong #NextRuler+NextRuler	PushzWord <MyId	;Use this as myid	PushWord #$C000	;changed to Locked HY 5/5/88	pha	pha	_NewHandle	;get new handle	bcc newH	pha	;push error code	brl cleanUpstack	;clean things upnewH	pla	sta TERec	;get TEREC handle	pla	sta TERec+2	PushzLong <TERec	;opt 22-Aug-91 DAL	jsr Deref	pla	sta LineRuler	pla	sta LineRuler+2;====================================================================;;Actual routine;;setup;mainloop;cleanup;---------------------------------------------------------------;SetUp;SetUp;Get a NewRgn to be	set to the ClipRgn	pha	pha	_NewRgn	pla	sta ClipRgn	pla	sta ClipRgn+2	bcc GetCLip	;if no error continue	pha	;save error code	brl Handle1	;got an error.GetClip	PushzLong ClipRgn	;opt 22-Aug-91 DAL	_GetClip	bcc GetTextRgn	;if no error continue	pha	;save error code	brl ErrorClip	;got an error.;Get a NewRgn to be	set to the TextRect	areaGetTextRgn	pha	pha	_NewRgn	pla	sta TextRgn	pla	sta TextRgn+2	bcc RectRgn	;if no error continue	pha	;save error code	brl ErrorClip	;got an error.RectRgn	PushzLong TextRgn	;opt 22-Aug-91 DAL	PushzLong TextRectPtr  ;opt 22-Aug-91 DAL	_RectRgn	bcc GetBoxRgn	;if no error continue	pha	;save error code	brl ErrorText	;got an error.;Get a NewRgn for intersection of TextRgn and old clipping.GetBoxRgn	pha	pha	_NewRgn	pla	sta BoxRgn	pla	sta BoxRgn+2	bcc SectRgn	;if no error continue	pha	;save error code	brl ErrorText	;got an error.SectRgn	PushzLong ClipRgn	;opt 22-Aug-91 DAL	PushzLong TextRgn	;opt 22-Aug-91 DAL	PushzLong BoxRgn	;opt 22-Aug-91 DAL	_SectRgn	bcc SetClip	;if no error continue	pha	;save error code	brl ErrorBox	;got an error.;Reset the clipping	to my new clipping area.SetClip	PushzLong BoxRgn	;opt 22-Aug-91 DAL	_SetClip	bcc EraseRect	;if no error continue	pha	;save error code	brl ErrorBox	;got an error.;First do an EraseRect on the TextRectPtr area.EraseRect	PushzLong TextRectPtr  ;opt 22-Aug-91 DAL	_EraseRect;Calculate the FontHeight;Using TextRgn to as FontInfoPtr until I get the font Hieght	tdc	;transfer direct page to accumulator.	clc	adc #FontInfoRec	;add offset to record.	stz FontInfoPtr+2	;It's on directPage.	sta FontInfoPtr	;Store address.	PushzLong FontInfoPtr ;pass pointer	;opt 22-Aug-91 DAL	_GetFontInfo	;get the font info;Move the pen to the correct position.	ldy #2	lda [TextRectPtr],y	pha	;pass horizontal = to rect.	lda [TextRectPtr]	;Get the top.	ldy #2	sec	sbc [fontInfoPtr],y	;subtract descent.	sta CurrentHeight	;current vertical position	pha	;pass the vetical.	_MoveTo	stz CharLine	lda #1	sta CRFlag;------------------------------------------------------------------------;;SavePort;*** Using GetFontGlobals was silly, since we have GetFontLore.*** 22-Aug-91 DAL -- use GetFontLore to find font information	pha	;space for GetFontLore result	pea 0	tdc	clc	adc #theFontGlobals	pha	pea $000E	;size we want	_GetFontLore	pla*** end 22-Aug-91 DAL;Save Font Family Number	lda <theFontGlobals	;DAL	ldy #FamNum	sta [LineRuler],y	ldy #FamNum+NextRuler	sta [LineRuler],y;Save Font Size/Style	lda <theFontGlobals+4  ;get size (22-Aug-91 DAL)	and #$00FF	;mask off hi byte	xba	;put size in hi byte	pha	;and save	lda <theFontGlobals+2  ;get style (22-Aug-91 DAL)	and #$00FF	;mask off hi byte	ora 1,s	;OR with size	plx	;clean up stack	ldy #SizeStyle	sta [LineRuler],y	ldy #SizeStyle+NextRuler	sta [LineRuler],y;Save Color	pha	;space for result	_GetBackColor	ldy #NextRuler+BGroundColor	pla	;get index	sta [LineRuler],y	;save background color	pha	;space for result	_GetForeColor	ldy #NextRuler+FGroundColor	pla	;get index	sta [LineRuler],y	;save background color	lda #0	ldy #LeftMargin	sta [LineRuler],y	ldy #RightMargin	sta [LineRuler],y;zero Extra spacing	ldy #ExtraSpacing	sta [LineRuler],y	stz LastFullChar	stz LastPartChar	stz MaxLine	stz <PrintedSomeChars  ;added 4-Sep-91 DAL	jsr GetMaxWidth;=========================================================================;;MainLoop;MainLoop	jsl ResetVariables	;varibles for each new line.	jsl GetALine	;GetALine to print.	lda <CurrentHeight	   ;added 4-Sep-91 DAL	sta <oldCurrentHeight  ;added 4-Sep-91 DAL	jsr NewLine	;reset pen.	jsl OutputLine	;Print that line.	lda CRFlag	;get crFlag.	beq @NoCr	;if not a cr, don't count it.	lda #1	;Amount to bump.	jsr BumpTextPtr	;Bump the TextPtr.@noCR*** added 4-Sep-91 DAL	lda <PrintedSomeChars	ora <CRFlag	bne @ok	lda <oldCurrentHeight	sta <CurrentHeight	bra MainLoop@ok*** end 4-Sep-91;Loop Until InputDone or TextLen <= 0 or VPos > RectBottom + Height	lda InputDone	;Get InputDone.	bne MLExit	;Exit if InputDone.	ldy #4	;Get offset to Bottom.	lda [TextRectPtr],y	;Get Bottom.	cmp CurrentHeight	;Compare with Current V Pos.	bmi MLExit	;If out of view Exit.	lda TextLen	;Get TextLen.	bne MainLoop	;if still has text don't quit.MLExitquit	jsr ResetPort	;put port back to how it was.;------------------------------------------------------------------;;End of Main Loop;;--------------------------------------------------------------------;;Clean up stuff;CleanUp	pea 0	;clear error code.	PushzLong ClipRgn	;opt 22-Aug-91 DAL	_SetClipErrorBox	PushzLong BoxRgn	;opt 22-Aug-91 DAL	_DisposeRgnErrorText	PushzLong TextRgn	;opt 22-Aug-91 DAL	_DisposeRgnErrorClip	PushzLong ClipRgn	;opt 22-Aug-91 DAL	_DisposeRgnHandle1	PushzLong TERec	;get rid of TERec handle ;opt 22-Aug-91 DAL	_DisposeHandleCleanUpStack	plx	;get the error code	into x.Exit	;-----------------------------------------------------------;; Now take grafport fields off the stack and put back into; the port. ;	stx Temp	; save error code in temp	pha	; get current port ptr	pha	_GetPort	lda 2,s	; set dbr to bank of port	pha	plb	plb	plx	; put ptr in x	pla	; ignore high word	ldy #opicSave-ofontHandle-2	; use this as count@1	pla	; get word off stack and write into port	sta |opicSave-2,x		dex	dex	dey	dey	bpl @1	; repeat until y < 0	plb	; restore dbr	ldx Temp	; get error code (if any) back.	PushzWord <rtl1+4	PushzWord <rtl1+2	PushzWord <rtl1	lda OrigDirect	tcd	;reset direct page	txa	;get error code in a	cmp #1	;set c bit occordingly	rtl;---------------------------------------------------------------------;;GetOffset;;Adds CharLine and TokenLength and leaves it in the accumulator.;GetOffset	lda CharLine	;get charline	clc	adc TokenLength	;add the tokenLength to it.	rts;-----------------------------------------------------------------------;;Deref;;Derefrences the handle, or pointer on the stack and puts it back on the;Stack.  Uses TempPtr as temporary storage for pointer.;Deref	pla	sta Temp	;get return address.	pla	;get low word	sta TempPtr	;save in FontInfoPtr	pla	;get High word	sta TempPtr+2	;save in FontInfoPtr	ldy #2	lda [TempPtr],y	pha	lda [TempPtr]	;deref to low word	pha	;put on stack	PushzWord <Temp	;Push return address	rts;----------------------------------------------------------------------------;;ResetVariables;ResetVariables	ldy #6	lda [FontInfoPtr],y	sta LastLeading	stz TokenLength	stz CurrentSpaces	stz Tabs	stz CurrentWidth	stz Spaces	stz CharLine	stz MaxHeight	stz Change	stz ChangeFlg	stz GotFChange	rtl;------------------------------------------------------------------;; Get the MaxWidth;GetMaxWidth	ldy #6	lda [TextRectPtr],y	;get right most pixel	ldy #2	sec	sbc [TextRectPtr],y	;sub left most pixel	ldy #LeftMargin	sec	sbc [LineRuler],y	ldy #RightMargin	sec	sbc [LineRuler],y	sta MaxWidth	;save result as MaxWidth	rts;==================================================================;;MainLoop Routines;;-------------------------------------------------------------;Uses Flags: CRFlag	init 1; LineDone loc GetALine dep MaxWidth; InputDone init 0;         Nothing.;;------------------------------------------------------------------;BumpTextPtr (Bump);BumpTextPtr	sta Temp	;Save the bump.	lda LastPartChar	sta LastFullChar	clc	adc Temp	sta LastPartChar	lda Temp	;Save the Bump.	clc	adc TextPtr	;and add the Bump to it.	sta TextPtr	lda TextPtr+2	;bump the high word	adc #0	;and add the Bump to it.	sta TextPtr+2	lda TextLen	;get the Length.	sec	sbc Temp	sta TextLen	rts	;finished;---------------------------------------------------------------------;;GetALine;1. Gets A line to be Drawn;2. No Leading Blanks, unless needed because of (LeftJ or FillJ) and CRFlag.;3. No Traling Blanks.;4. Returns CharLine which is # of Char	to be drawn from TextPtr.;5. Will do 4 above	even if it has to break a word to fit.;;GetALine	jsr UpdateHeight	inc Nothing	;Set Nothing to True.	stz LineDone	;Set LineDoen to False.	stz InputDone	;set input done to False.;The following lines have been commented out so that leading blanks are stripped;correctly when the	previous line was left or fill justified and this line will;be right or center	justified.   5-8-87	CAE;              lda	    CRFlag	       ;Get CRFlag.;              beq	    SkpngBlanks	       ;if not CRFlag then go to loop.;              lda	    TextJust	       ;get TextJustification.;              beq	    GALRepeat	       ;if left just don't skip blanks.;              cmp	    #2	       ;compare just with fill.;              beq	    GALRepeat	       ;if fill then don't skip blanks.SkpngBlanks	inc Skiping	jsr ScanBlanks	;ScanBlanks at Begining of line.	lda CRFlag	beq Skip	lda TextJust	;get TextJustification.	beq GALRepeat	;if left just don't skip blanks.	cmp #2	;compare just with fill.	beq GALRepeat	;if fill then don't skip blanks.Skip		;	jsr GetOffset	;get # of Spaces to	skip.	jsr BumpTextPtr	;Bump text ptr passed blanks.	stz CharLine	stz TokenLength	;zero the variables	used...	stz Tabs	;...to get the blanks.	stz SpacesGALRepeat	stz Skiping	jsr ScanBlanks	;calculate blanks.	jsr ScanToken	;get a token.	jsr CheckDone	;set lineDone if I'm done.	lda InputDone	;if input done then	quit.	bne GALExit	;else continue normally.	lda LineDone	;get LineDone.	beq NotDone	;Keep going if not done.	stz Inputdone	;else don't quit completly.	lda Nothing	;Get nothing.	beq NotDone	;if Nothing false keep going.	jsr BrkToken	;Have only one token, brk it.NotDone	ldy CharLine	;get offset to first char.	lda [TextPtr],y	;get char.	and #$00FF	;get only one char.	cmp #$0d	;see if it's a CR.	bne NotACR	;if not a cr then branch.	inc CRFlag	;set crFlag true.	rtl	;cr so exit and print the line.NotACR	stz CRFlag	;set CRFlag to false.GALUntil	lda LineDone	;get line done.	bne GALExit	;if line done exit.	lda CRFlag	;get CRFlag.	bne GALExit	;if CRFlag then exit.	bra GALRepeat	;Else continue repeating.GALExit	rtl	;exit.;---------------------------------------------------------------------;;OutputLine;1. DrawsText of length CharLine from TextPtr.;2. DrawsText in approptiate justification.;3. Positions cursor to left of newline.;;----------------------------------------------------------------------OutputLine	lda TextJust	;get justification.	beq Draw	;Check if Left if so draw.	bmi Right	;Check if Right justified.	cmp #2	;Check if Center justified.	bne Center	;if so do center, else do fill.Fill	lda CrFlag	;(Matt says this will)	ora InputDone	;Don't fill last line.	bne Draw	;(make everything perfect)	lda CurrentSpaces	;get number of spaces.	bne GetSpaceX	;if not zero divide.	inc CurrentSpaces	;else set spaces to	1.GetSpaceX	pha	pha	;optimized 19-Sep-90 DAL	lda MaxWidth	;get max width.	sec	sbc CurrentWidth	;get the width used.	pha	;push result of subtract.	PushzWord <CurrentSpaces ;push denominator.	_FixRatio	;get fixed ratio.	_SetSpaceExtra	;set the extra space.	bra Draw	;now draw it.Center	lda MaxWidth	;get max width.	sec	sbc CurrentWidth	;get the width used.	lsr A	;divide by 2.	pha	;push hor pos.	PushWord #0	;push zero change ver.	_Move	;move to appropriate spot.	bra Draw	;now draw it.Right	lda MaxWidth	;get MaxWidth.	sec	sbc CurrentWidth	;get horizontal pos.	pha	;push the hor pos.	PushWord #0	;Push Vertical change.	_Move	;Move to approriate	spot.Draw	jsr DrawLine	;draw the line.	PushLong #0	;setspace extra to zero...	_SetSpaceExtra	rtl;----------------------------------------------------------------------;;DrawLine;;----------------------------------------------------------------------DrawLine	stz TokenLength	;Start Printing the	line.	lda Change	;Change on this line?	beq NoChange	;If not print the line.	jsr SetRuler	;Set paramters to start of line.Loop	lda CharLine	;Get length of string.	cmp TokenLength	beq DrawRest	;If all of them are	printed.	bmi DrawRest	;if done draw remaining text.	lda TokenLength	;pass offset	jsr LoadChar	;Get the next Char.	cmp #DeltaFlg	;Is Char a delta flag.	bne NextChar	;If not do next char.	jsr DrawPart	;draw part parsed so far.BumpingTP	lda TokenLength	;Get Amount drawn.	jsr BumpTextPtr	;bump it.	lda CharLine	;Get Length of string	sec	sbc TokenLength	;subtract amount just drawn.	sta CharLine	;save new length of	line.	lda #1	sta TokenLength	;reset TokenLength to one.	jsr LoadChar	;get which change.	inc TokenLength	;get ready to load word	lda TokenLength	jsr GetDeltaWord	;get the DeltaWord	sta Temp	jsr DoDelta	;take care of delta	bra LoopNextChar	inc TokenLength	bra LoopNoChange	lda CharLine	;get length	sta TokenLength	;get ready to print	it.DrawRest	jsr DrawPart	;draw the rest of the loop.	lda TokenLength	jsr BumpTextPtr	rts;-------------------------------------------------------------------------;;DoDelta;;----------------------------------------------------------------------DoDelta	lda Char	cmp #S	;see if style change.	bne TestF	PushzWord <Temp	;push the word from	GetWord.	_SetTextFace	;Set the text Face.	ldy #SizeStyle	lda [LineRuler],y	;get size/style	and #$FF00	;mask off previous style	ora Temp	;OR in new style	sta [LineRuler],y	;and save in ruler.	jsr UpDateHeight	;Check if height has changed.	bra DoBpDeltaTestF	cmp #F	;see if font change.	bne TestC	lda #1	sta <GotFChange	inc TokenLength	;get next word.	inc TokenLength	lda TokenLength	jsr GetDeltaWord	;get new size/style	ldy #SizeStyle	sta [LineRuler],y	;and save in ruler	jsr DoFont	;take care of the font.	lda Temp	;get new fam num	ldy #FamNum	sta [LineRuler],y	;and save in ruler.	jsr UpDateHeight	;See if maxHeight has changed.	lda #6	;number to bump.	jsr BumpDelta	rtsTestC	cmp #C	;check if fore color change.	bne TestB	PushzWord <Temp	;Push the index to color table.	_SetForeColor	bra DoBpDeltaTestB	cmp #B	;check if background color.	bne TestOther	PushzWord <Temp	;Push the index to color table.	_SetBackColor	bra DoBpDeltaTestOther	cmp #J	beq DoBpDelta	;skip delta data.	cmp #Q	beq DoBpDelta	cmp #X	beq DoBpDelta	cmp #L	beq DoBpDelta	cmp #M	beq DoBpDelta	jsr DoRulerDoBpDelta	lda #4	;bump normal delta.	jsr BumpDelta	rts;-------------------------------------------------------------------------;;BumpDelta;;----------------------------------------------------------------------BumpDelta	sta Temp	jsr BumpTextPtr	lda CharLine	;GetNumber of Chars	left.	sec	sbc Temp	;subtract the delta	string.	sta CharLine	;and save new value.	stz TokenLength	rts;--------------------------------------------------------------------------;SetRuler;;Takes the ChangeFlg and sets each paramater that is marked	for change.;;----------------------------------------------------------------------SetRuler	lda ChangeFlg	beq AllSet	;no changes, so quit.	lsr ChangeFlg	;get Style bit	bcc CheckFont;set style	ldy #SizeStyle	lda [LineRuler],y	;get size/style	and #$00FF	;mask off size	pha	_SetTextFace	lda ChangeFlg	beq AllSetCheckFont	lsr ChangeFlg	;get Font bit.	bcc AllSet	ldy #FamNum	lda [LineRuler],y	sta Temp	;save in Temp for DoFont call.	ldy #SizeStyle	lda [LineRuler],y	jsr DoFontAllSet	rts;allow R (ruler) change someday;----------------------------------------------------------------------;;DrawPart;1. Draws Text of length CharLine from TextPtr.;2. Positions Cursor to left on new line.;3. resets currentHeight.;;----------------------------------------------------------------------DrawPart*** added/opt 22-Aug-91 DAL	lda <TokenLength	beq Drawn	PushZLong <TextPtr	;pass the pointer.	pha	;push the length	_DrawText	inc <PrintedSomeChars  ;added 4-Sep-91 DALDrawn	rts*** end 22-Aug-91;----------------------------------------------------------------------;;NewLine;;----------------------------------------------------------------------NewLine	ldy #2	;get offset to left.	lda [TextRectPtr],y	;get left.	ldy #LeftMargin	clc	adc [LineRuler],y	pha	;push horizontal.	lda MaxLine	beq addMHeight	clc	adc CurrentHeight	bra addFontAddMHeight	lda CurrentHeight	;get current height	clc	adc MaxHeight	;add MaxHeight change.AddFont	ldy #6	sec	sbc [FontInfoPtr],y	clc	adc LastLeading	ldy #ExtraSpacing	clc	adc [LineRuler],y	sta CurrentHeight	;save result as new	cur height.	pha	;push vert. position.	_MoveTo	;move to new line.	rts;---------------------------------------------------------------;;ScanBlanks;;----------------------------------------------------------------------ScanBlanks	jsr GetNextChar	;get the next char in char.	lda InputDone	;get input done.	bne ExitSB	;if set exit ScanBlanks	lda Char	;get the char.	cmp #$20	;compare with space.	bne CkTbChar	;if not a space Check if tab.	inc Spaces	;increment number of spaces.	inc TokenLength	;and number of tokens.	bra ScanBlanks	;keep scaning until	exit.CkTbChar	cmp #$09	;check if char is a	tab.	bne ExitSB	;exit ScanBlanks if	not a tab.	inc Tabs	;else increment # of tabs.	inc TokenLength	;and number of tokens.	bra ScanBlanks	;keep scaning until	exit.ExitSB	rts	;Done scanning blanks.;---------------------------------------------------------------;;ScanToken;ScanToken	jsr GetNextChar	;get the next char.	lda InputDone	;get input done.	bne STExit	;if set exit scan token.	lda Char	;else get the char.	cmp #$20	;check if space.	beq STExit	;if a space than exit.	bpl Token	;if gt it's still a token.	cmp #$09	;check if tab	beq STExit	;if so then exit.	cmp #$0D	;check if CR	beq ItsACR	;if so then count it and exit.	cmp #DeltaFlg	beq ItsACR	;if delta flag exit.Token	inc TokenLength	;it's a token so inc toklen.	bra ScanToken	;keep going until exit.ItsACr	inc LineDone	;set line done, to exit on cr.STExit	rts;------------------------------------------------------------------;;GetNextCharGetNextChar	jsr GrabChar	;Get the nextchar	lda InputDone	bne GNCExit	lda char	cmp #DeltaFlg	;Is char deltaflg marker?	bne GNCExit	;If not exit	inc Change	;A delta exists on this line.	jsr CheckDone	;Check if current stuff fits.	lda LineDone	;Get line done.	bne GNCExit	;if done then exit	inc TokenLength	;pass DeltaFlg	jsr GetOffset	;add TokenLength and CharLine.	jsr LoadChar	;What kind of delta	is it?	inc TokenLength	;account for marker.	jsr GetOffset	;Add TokenLength and CharLine.	jsr GetDeltaWord	sta Temp	;store delta word in temp.	lda Char	cmp #S	bne ChkFont	PushzWord <Temp	;Push the delta word.	_SetTextFace	;set the textface.	lda Skiping	beq NoSkip1	ldy #SizeStyle	lda [LineRuler],y	;get size/style	and #$FF00	;mask off previous style	ora Temp	;OR in new style	sta [LineRuler],y	;and save in ruler.	brl DeltaEndNoSkip1	lda ChangeFlg	;get ChangeFlg.	ora #$0001	;set style flg.	sta ChangeFlg	;save the change.	brl DeltaEndGNCExit	rtsChkFont	cmp #F	;See if Font Change.	bne ChkColorChng	;if not check if a color change.	inc TokenLength	inc TokenLength	jsr GetOffset	jsr GetDeltaWord	;get size/style	ldx Skiping	beq NoSkip2	ldy #SizeStyle	sta [LineRuler],y	;save new size/style in rulerNoSkip2		;	jsr DoFont	;Take care of the font change.	lda Skiping	beq NoSkip3	lda Temp	ldy #FamNum	sta [LineRuler],y	brl DeltaEndNoSkip3	lda ChangeFlg	;get ChangeFlg.	ora #$0002	;set Font flg.	sta ChangeFlg	;save the change.	bra DeltaEndChkColorChng	cmp #C	bne ChkQ	lda Skiping	;bug fix 5-6-87 CAE	beq DeltaEnd	PushzWord <Temp	_SetForeColor	;end bug fix	bra DeltaEndChkQChkBGround	cmp #B	bne ChkExtra	lda Skiping	;bug fix 5-6-87 CAE	beq DeltaEnd	PushzWord <Temp	_SetBackColor	;end bug fix	bra DeltaEndChkExtra	cmp #X	bne CheckLMargin	ldy #ExtraSpacing	lda Temp	sta [LineRuler],y	bra DeltaEndCheckLMargin	cmp #L	bne CheckRMargin	ldy #LeftMargin	lda Temp	sta [LineRuler],y	jsr GetMaxWidth	bra DeltaEndCheckRMargin	cmp #M	bne CheckJust	ldy #RightMargin	lda Temp	sta [LineRuler],y	jsr GetMaxWidth	bra DeltaEndCheckJust	cmp #J	bne CheckRuler	lda Temp	sta TextJust	bra DeltaEndCheckRuler	cmp #R	bne DeltaEnd	jsr DoRuler	;mark new ruler	bra DeltaEndDeltaEnd	jsr CountDelta	brl GetNextChar	;continue;-----------------------------------------------------------------------------;CountDelta	inc TokenLength	inc TokenLength	jsr GetOffset	;add TokenLength and charLine.	sta CharLine	;store in CharLine	stz TokenLength	rts;----------------------------------------------------------------------------;GrabChar	jsr GetOffset	;Add CharLine and TokenLength	sta OffSet	;to get total OffSet.	cmp TextLen	;compare it to OffSet.	bpl getoutStillInputLeft	jsr LoadChar	;get the char.	bra GCExitgetout	inc Inputdone	;and put in input done.GCExit	rts;------------------------------------------------------------------;;LoadChar;;Puts next char in char variable, from TextPtr with an offset in the accum.;LoadChar	tay	;put OffSet in y.	lda [TextPtr],y	;get charachters.	and #$00FF	;get only one Char.	sta char	;store in Char.	rts;----------------------------------------------------------------;;DoRuler;DoRuler		;needs to handle the rulers	rts	;for future R change;-----------------------------------------------------------------------;;UpDateHeight;UpDateHeight	jsr GetHeight	cmp MaxHeight	bcc smaller	sta MaxHeight	;It's bigger so save it.smaller	rts;----------------------------------------------------------------------;;GetHeight;GetHeight	tdc	;transfer direct page to accumulator.	clc	adc #FontInfoRec	;add offset to record.	stz FontInfoPtr+2	;It's on directPage.	sta FontInfoPtr	;Store address.	PushzLong FontInfoPtr ;pass pointer	;opt 22-Aug-91 DAL	_GetFontInfo	;get the font info	lda [FontInfoPtr]	;get ascent	ldy #6	clc	adc [FontInfoPtr],y	;add leading.	ldy #2	clc	adc [FontInfoPtr],y	;add descent.	rts;--------------------------------------------------------------------;;ResetPort;;Resets the Port back to the way it was	when textbox was called.;ResetPort		;	ldy #SizeStyle+NextRuler	lda [LineRuler],y	;get size/style	and #$00FF	;mask off size	pha	_SetTextFace	;set style	lda <GotFChange	beq NoFontChange	ldy #FamNum+NextRuler	lda [LineRuler],y	sta Temp	ldy #SizeStyle+NextRuler	lda [LineRuler],y	jsr DoFontNoFontChange	ldy #FGroundColor+NextRuler	lda [LineRuler],y	pha	_SetForeColor	;set foreground color	ldy #BGroundColor+NextRuler	lda [LineRuler],y	pha	_SetBackColor	;set Background color	rts;----------------------------------------------------------------------;;DoFont;DoFont	pha	;Push the size and style.	PushzWord <Temp	;push the fam num	PushWord #0	;scaling.	_InstallFont	;Change the font.	bcc FontInstalled	;font installed, no	error.	rts	;exit there was an error.FontInstalled		;	jsr UpdateHeight	;reset Height dependencies.	clc	;clear carry if no error.	rts;--------------------------------------------------------------;;GetDeltaWord;;Returns the word, at TextPtr with offset in the accum., in	the accum.;GetDeltaWord	tay	;put it y for offset	lda [TextPtr],y	;get the word	rts;--------------------------------------------------------------;;CheckDoneCheckDone;	Pushword #0	;Push Space for result.	pha	lda TextPtr	;get low word of TextPtr.	clc	adc CharLine	;add offset to it.	sta Temp	;save low word.	lda TextPtr+2	;get high word.	adc #0	;add carry to highword.	pha	;push high word.	PushzWord <Temp	;push low word.	PushzWord <TokenLength ;push length of text	_TextWidth	;get the textwidth.	pla	;get the width.	clc	adc CurrentWidth	;add to CurrentWidth.	cmp MaxWidth	;are we past the limit?	beq MoreToDo	bmi MoreToDo	;if so, we're done	stz inputDoneSetLineDone	inc LineDone	;and store it in line done.	rtsMoreToDo	sta CurrentWidth	jsr GetOffset	;add charline and TokenLength.	sta CharLine	;save CharLine	lda Spaces	;Get # of spaces.	clc	adc CurrentSpaces	;add to currentspaces.	sta CurrentSpaces	;save current spaces.	stz Spaces	;clear spaces.	stz TokenLength	;clear TokenLength.	stz Nothing	;set nothing to false.CDExit	rts	;done.;------------------------------------------------------------;;BrkTokenBrkToken	dec TokenLength	;TokenLength =- 1	jsr CheckDone	;check if done.	lda TokenLength	;get tokenLength.	bne BTUntil	;check until condition.	lda CharLine	;get charline	bne BTUntil	;if nothing will fit quit!	stz LineDone	;finished so set exit.	inc InputDone	;inputdone = 1BTUntil	lda TokenLength	;get lineDone.	bne BrkToken	;if not zero keep backing up.	inc LineDone	;Linedone = 1.	rts	EndP	print POP*****************************************************************FakeGetLEDefProc 	PROC** Jumps to code in dynamic segment so address of dynamic* segment is not in tool table.*** Inputs:*	space for output** Outputs:*	space for output** External Refs:	import GetLEDefProc** Entry Points:*	none*	longa on	; mode	longi on*** Added 15 May 89	Steven Glass*****************************************************************	jml GetLEDefProc	EndP****************************************************************** LEClassifyKey -- new call 20-Mar-92 DAL for 6.1** Input:  pointer to event record* Output: word, bit flags*           15: special editing key*           14: digit (0-9)*           13: hex digit (a-f, A-F)*           12: letter (A-Z, a-z)*           11: non-control key*            0: any key*****************************************************************LEClassifyKey	proc	phd	tsc	tcdevent	equ 9result	equ event+4	stz <result	lda [<event]	cmp #keyDownEvt	beq @key	cmp #autoKeyEvt	bne @notKey@key	ldy #2	;offset to message	lda [<event],y	inc <result	ldx #TableEnd-Table-4@search	sep #$20	cmp >Table,x	rep #$20	bcc @next	sep #$20	cmp >Table+1,x	rep #$20	bcs @next	tay	lda >Table+2,x	tsb <result	tya@next	dex	dex	dex	dex	bpl @search@notKey	pld	ldx #0	;no error	ldy #4	;strip 4 bytes	jml $e10184	;ToStrip	macro&lab	keyRange &low,&high,&mask&lab	dc.b &low,1+&high	dc.w &mask	mendTable	keyRange $06,$06,$8000	keyRange $08,$08,$8000	keyRange $15,$15,$8000	keyRange $18,$19,$8000	keyRange $7f,$7f,$8000	keyRange '0','9',$4000	keyRange 'A','F',$2000	keyRange 'a','f',$2000	keyRange 'A','Z',$1000	keyRange 'a','z',$1000	keyRange $20,$FE,$0800TableEnd	EndP	END